window.DECKS=[{"id": "wk01-intro", "title": "Week 1 - Course Introduction", "pages": 15}, {"id": "wk01-natural", "title": "Week 1 - Natural Materials", "pages": 41}, {"id": "wk02-engmaterials", "title": "Week 2 - Engineering Materials", "pages": 146}, {"id": "wk03-properties", "title": "Week 3 - Properties of Materials & Selection", "pages": 99}, {"id": "wk04-casting", "title": "Week 4 - Metals: Liquid State Forming (Casting)", "pages": 74}, {"id": "wk05-forming", "title": "Week 5 - Metals: Plastic & Solid State Forming", "pages": 78}, {"id": "wk06-thermoplastics", "title": "Week 6 - Polymers: Thermoplastic Processes", "pages": 65}, {"id": "wk07-thermosets", "title": "Week 7 - Polymers: Thermosets & Composites", "pages": 86}, {"id": "wk08-cutting", "title": "Week 8 - Metals: Cutting & Machining", "pages": 91}, {"id": "wk09-joining", "title": "Week 9 - Joining: Soldering, Brazing, Welding", "pages": 82}, {"id": "wk10-joining", "title": "Week 10 - Joining: Plastics, Adhesives, Fasteners", "pages": 83}, {"id": "wk13-ceramics", "title": "Week 13 - Ceramics, Glass, Carbon, RHMs", "pages": 56}];
window.QUESTIONS=[{"d":"wk01-intro","p":10,"q":"The ID2322 final examination is a:","o":["2-hour open book paper","90-minute closed book written paper","60-minute online quiz","90-minute open book paper"],"h":"Check the Final Examination slide.","a":1,"id":0},{"d":"wk01-intro","p":7,"q":"In ID2322, the final examination contributes what percentage of the total grade?","o":["60%","50%","40%","10%"],"h":"CA makes up the remaining 60%.","a":2,"id":1},{"d":"wk01-intro","p":5,"q":"According to the ID2322 syllabus, forging, rolling, extrusion and thermoforming are classed as:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Joining processes"],"h":"The material is soft/deformable but not molten.","a":1,"id":2},{"d":"wk01-intro","p":5,"q":"According to the ID2322 syllabus, castings and mouldings are:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Machining processes"],"h":"The material is shaped while molten.","a":0,"id":3},{"d":"wk01-intro","p":5,"q":"Cutting, bending and stamping are classified in the syllabus as:","o":["Liquid state forming processes","Plastic state forming processes","Solid state forming processes","Additive processes"],"h":"The material stays solid at room temperature.","a":2,"id":4},{"d":"wk01-natural","p":2,"q":"The smallest part of an element that retains the properties of that element is the:","o":["Molecule","Crystal","Atom","Grain"],"h":"It is the building block of all engineering materials.","a":2,"id":5},{"d":"wk01-natural","p":4,"q":"Organic materials are best defined as materials that:","o":["Contain no carbon and do not decay","Originate from living organisms, usually contain carbon and are capable of decay","Are formed only through geological processes","Are always man-made synthetics"],"h":"Think of wood, cotton, bone and crude oil.","a":1,"id":6},{"d":"wk01-natural","p":5,"q":"Which of the following is an inorganic material?","o":["Silk","Crude oil","Cotton","Sand"],"h":"Inorganic materials are not derived from living things.","a":3,"id":7},{"d":"wk01-natural","p":4,"q":"Which of the following is NOT an organic (biotic) material?","o":["Linoleum","Chitin","Granite","Horn"],"h":"Rocks come from the ground, not from living organisms.","a":2,"id":8},{"d":"wk01-natural","p":6,"q":"Plastics engineers deal primarily with ______ substances.","o":["organic","inorganic","metallic","ceramic"],"h":"Polymers are carbon-based.","a":0,"id":9},{"d":"wk01-natural","p":6,"q":"Metallurgists and ceramists deal primarily with:","o":["Organic substances","Inorganic substances","Biological substances","Polymeric substances"],"h":"Metals and ceramics are not derived from living things.","a":1,"id":10},{"d":"wk01-natural","p":7,"q":"A natural material is any product or physical matter that comes from:","o":["Factories, refineries or laboratories","Plants, animals or the ground","Recycled consumer waste only","Petroleum-based feedstocks only"],"h":"Three natural sources are listed.","a":1,"id":11},{"d":"wk01-natural","p":8,"q":"Clay and porcelain are listed under natural inorganic materials as:","o":["Metals","Stones","Composites","Natural fibres"],"h":"They are mixtures of several minerals.","a":2,"id":12},{"d":"wk01-natural","p":11,"q":"Cork is harvested commercially mainly from the cork oak tree, with which country producing about 50% of the world's cork?","o":["Spain","Portugal","Italy","France"],"h":"An Iberian country famous for wine stoppers.","a":1,"id":13},{"d":"wk01-natural","p":11,"q":"Cork is well suited for wine bottle stoppers mainly because of its:","o":["High hardness and brittleness","Elasticity combined with near-impermeability","High thermal conductivity","High density"],"h":"It must seal tightly and keep liquid in.","a":1,"id":14},{"d":"wk01-natural","p":14,"q":"Hardwood trees are characterised by:","o":["Broad leaves, producing fruit or nuts, and generally going dormant in winter","Needles and cones","Always being harder than softwoods","Growing only in cold climates"],"h":"Think of teak or oak versus pine.","a":0,"id":15},{"d":"wk01-natural","p":14,"q":"Which of the following is a softwood?","o":["Teak","Rosewood","Pine","Ramin"],"h":"Softwoods are conifers that bear cones.","a":2,"id":16},{"d":"wk01-natural","p":16,"q":"Which of the following is listed as a South East Asian hardwood?","o":["Spruce","Cedar","Fir","Nyatoh"],"h":"The others are conifers.","a":3,"id":17},{"d":"wk01-natural","p":17,"q":"Plywood, compressed wood board and MDF are examples of:","o":["Natural solid woods","Wood composites (engineered wood)","Softwoods","Wood-free polymers"],"h":"They are made by binding strands, fibres or boards of wood together.","a":1,"id":18},{"d":"wk01-natural","p":17,"q":"MDF stands for:","o":["Multi-Directional Fibreboard","Medium Density Fibreboard","Moulded Density Fibre","Machined Dense Finish"],"h":"It is an engineered wood board.","a":1,"id":19},{"d":"wk01-natural","p":21,"q":"Leather is created through the ______ of animal hides and skins.","o":["Vulcanisation","Tanning","Sintering","Curing"],"h":"The process prevents decomposition.","a":1,"id":20},{"d":"wk01-natural","p":23,"q":"Tanning converts putrescible skin into non-putrescible leather. \"Putrefaction\" refers to:","o":["Hardening of collagen","Decomposition of animal proteins","Removal of hair","Dyeing of the hide"],"h":"Putrescible means it can rot.","a":1,"id":21},{"d":"wk01-natural","p":24,"q":"Which leather is used for items that need to be strong but flexible, such as motorcycle gloves?","o":["Lamb leather","Kangaroo leather","Buffalo leather","Deer skin"],"h":"An Australian animal.","a":1,"id":22},{"d":"wk01-natural","p":24,"q":"Which leather is considered among the finest and most durable in the world?","o":["Cow hide","Sting ray leather","Ostrich leather","Buffalo leather"],"h":"A large flightless bird.","a":2,"id":23},{"d":"wk01-natural","p":22,"q":"In the leather industry, compared to the fur industry:","o":["The hide is a by-product of the meat industry, the meat being of higher value","The meat is a by-product of the hide","Only exotic animals are used","Hair is always left attached"],"h":"In the fur industry it is the opposite.","a":0,"id":24},{"d":"wk01-natural","p":27,"q":"Cow/buffalo horn combs are made from keratin. A key benefit claimed for them is:","o":["High electrical conductivity","Zero static electricity","Magnetic properties","Heat resistance above 1000°C"],"h":"Plastic combs cause frizz through this effect.","a":1,"id":25},{"d":"wk01-natural","p":33,"q":"Minerals are:","o":["Any material dug from the ground including rocks","Natural compounds formed through geological processes, defined by chemical composition and structure","Man-made crystalline compounds","Organic compounds formed by living things"],"h":"The study of them is mineralogy.","a":1,"id":26},{"d":"wk01-natural","p":34,"q":"To be classified as a \"true\" mineral, a substance must be:","o":["A liquid or solid with any structure","Organic and amorphous","A naturally occurring solid with a crystal structure and defined chemical composition","A mixture of rocks and mineraloids"],"h":"Three criteria: solid, crystalline, naturally occurring and homogeneous.","a":2,"id":27},{"d":"wk01-natural","p":35,"q":"On the Mohs scale, hardness is defined as resistance to:","o":["Indentation","Bending","Scratching","Impact"],"h":"You test it by scratching one mineral with another.","a":2,"id":28},{"d":"wk01-natural","p":35,"q":"On the Mohs scale of mineral hardness, which mineral has a hardness of 1?","o":["Talc","Gypsum","Quartz","Calcite"],"h":"The softest mineral, used in powder.","a":0,"id":29},{"d":"wk01-natural","p":35,"q":"Quartz has a Mohs hardness of:","o":["5","6","7","9"],"h":"It sits between orthoclase feldspar and topaz.","a":2,"id":30},{"d":"wk01-natural","p":35,"q":"Corundum (Al2O3), with a Mohs hardness of 9, is the mineral form of:","o":["Silicon carbide","Aluminium oxide","Calcium carbonate","Silicon dioxide"],"h":"Its chemical formula is Al2O3.","a":1,"id":31},{"d":"wk01-natural","p":35,"q":"The Mohs scale is described as a purely ______ scale.","o":["ordinal","linear","logarithmic","absolute"],"h":"Diamond (10) is about 15x harder than quartz (7) in absolute terms.","a":0,"id":32},{"d":"wk01-natural","p":36,"q":"A rock is:","o":["A single pure mineral crystal","A naturally occurring aggregate of minerals and/or mineraloids","A man-made ceramic","An organic sediment"],"h":"Rocks are mixtures.","a":1,"id":33},{"d":"wk01-natural","p":38,"q":"Granite has begun to supplant marble as a monument material mainly because:","o":["It is cheaper to quarry","It is much more durable against acid rain","It is softer and easier to carve","It is lighter"],"h":"Marble is a carbonate that is attacked by acid.","a":1,"id":34},{"d":"wk01-natural","p":29,"q":"Good designers design with ecology in mind. This includes:","o":["Using endangered species to create exclusive products","Not designing products that use endangered species as material","Avoiding all natural materials","Using only metals"],"h":"Saving wildlife.","a":1,"id":35},{"d":"wk02-engmaterials","p":3,"q":"Engineering materials are classified into which four categories?","o":["Metals, polymers, glasses and woods","Metals, polymers, ceramics and composites","Ferrous, nonferrous, polymers and ceramics","Thermoplastics, thermosets, metals and ceramics"],"h":"Glass is a subset of one of the categories.","a":1,"id":36},{"d":"wk02-engmaterials","p":5,"q":"Which of the following is NOT a typical characteristic of metals?","o":["Crystalline structure","Opaque and lustrous","Poor electrical conductivity","Able to change shape permanently under external forces"],"h":"Think of copper wiring.","a":2,"id":37},{"d":"wk02-engmaterials","p":6,"q":"When two or more metals are combined together, the result is called a(n):","o":["Composite","Alloy","Copolymer","Cermet"],"h":"Brass and bronze are examples.","a":1,"id":38},{"d":"wk02-engmaterials","p":6,"q":"Sterling silver consists of:","o":["77% silver + 23% tin","92.5% silver + 7.5% copper","80% silver + 20% chromium","99.9% pure silver"],"h":"The copper adds hardness.","a":1,"id":39},{"d":"wk02-engmaterials","p":6,"q":"Bell metal is an alloy of:","o":["Copper 77% + tin 23%","Copper 60% + zinc 40%","Nickel 80% + chromium 20%","Silver 92.5% + copper 7.5%"],"h":"It is a type of bronze with high tin content.","a":0,"id":40},{"d":"wk02-engmaterials","p":6,"q":"Nichrome, used for heating elements, is an alloy of:","o":["Nickel and copper","Nickel and chromium","Chromium and iron","Nickel and tin"],"h":"The name gives it away.","a":1,"id":41},{"d":"wk02-engmaterials","p":10,"q":"A metal can best be defined by the nature of its bonds, as:","o":["Solids with atoms sharing electrons in fixed pairs","Solids comprised of atoms held together by a matrix of electrons","Long carbon chains with weak secondary bonds","Ionic compounds of a metal and a non-metal"],"h":"The free electrons explain conductivity.","a":1,"id":42},{"d":"wk02-engmaterials","p":11,"q":"When a molten metal solidifies, its atoms arrange in a regular 3-dimensional pattern known as the:","o":["Grain boundary","Space lattice","Dislocation","Amorphous network"],"h":"This orderly arrangement repeats in 3D.","a":1,"id":43},{"d":"wk02-engmaterials","p":12,"q":"The smallest unit that makes up the building block of the space lattice is called the:","o":["Grain","Crystal","Unit cell","Dislocation"],"h":"Also called lattice cell.","a":2,"id":44},{"d":"wk02-engmaterials","p":13,"q":"How many basic unit cells can be identified?","o":["4","7","14","32"],"h":"These are the Bravais lattices.","a":2,"id":45},{"d":"wk02-engmaterials","p":15,"q":"Metals with a body-centred cubic (BCC) unit cell are normally characterised by:","o":["High melting point, high yield strength but low ductility","Low melting point and high ductility","Low plasticity and embrittlement in cold working only","High ductility and easy deformation"],"h":"Tungsten and molybdenum are examples.","a":0,"id":46},{"d":"wk02-engmaterials","p":15,"q":"Which of the following metals crystallises in a BCC structure?","o":["Copper","Aluminium","Tungsten","Zinc"],"h":"A very high melting point metal used in filaments.","a":2,"id":47},{"d":"wk02-engmaterials","p":16,"q":"Metals with an FCC structure tend to be:","o":["Brittle with high melting points","Ductile and easily deformed","Brittle when cold worked","Non-crystalline"],"h":"Copper, aluminium, gold are FCC.","a":1,"id":48},{"d":"wk02-engmaterials","p":16,"q":"Which group lists metals with an FCC arrangement?","o":["Copper, aluminium, lead, gold","Tungsten, molybdenum, vanadium","Beryllium, zinc, titanium, magnesium","Zinc, zirconium, magnesium"],"h":"These are all very ductile metals.","a":0,"id":49},{"d":"wk02-engmaterials","p":17,"q":"Metals with a hexagonal close-packed (HCP) structure, such as zinc, titanium and magnesium, tend to:","o":["Be highly ductile at room temperature","Have low plasticity and embrittle readily when cold worked","Have the highest melting points of all metals","Be non-magnetic and transparent"],"h":"Deformation only occurs readily on the 2 basal planes.","a":1,"id":50},{"d":"wk02-engmaterials","p":17,"q":"Which of the following metals has an HCP structure?","o":["Gold","Nickel","Magnesium","Vanadium"],"h":"Beryllium, zinc, titanium, zirconium are also HCP.","a":2,"id":51},{"d":"wk02-engmaterials","p":18,"q":"Metals are good conductors of electricity because:","o":["Electrons associated with each atom are free to move throughout the crystal","Their atoms are packed randomly","They contain long carbon chains","Their ions are fixed in place"],"h":"Current flow requires a flow of electrons.","a":0,"id":52},{"d":"wk02-engmaterials","p":20,"q":"In metals, loading tends to cause ______ rather than cleavage of the crystal.","o":["Crazing","Atomic slip","Crosslinking","Sintering"],"h":"Dislocations move along slip planes.","a":1,"id":53},{"d":"wk02-engmaterials","p":22,"q":"Metals are strengthened when dislocations:","o":["Move more freely","Meet more barriers to their motion","Are completely removed by melting","Are aligned in the flow direction"],"h":"The more barriers, the stronger the metal.","a":1,"id":54},{"d":"wk02-engmaterials","p":23,"q":"Adding larger impurity atoms to a pure metal to impede dislocation motion is called:","o":["Solid solution strengthening","Precipitation hardening","Quench hardening","Mechanical working"],"h":"The alloying atoms are dissolved in the host lattice.","a":0,"id":55},{"d":"wk02-engmaterials","p":25,"q":"Mechanical working (cold working) strengthens metals by:","o":["Dissolving impurity atoms","Multiplication of dislocations that interact and hinder each other","Trapping solute atoms by rapid quenching","Removing grain boundaries"],"h":"Bending a paper clip back and forth makes it harder.","a":1,"id":56},{"d":"wk02-engmaterials","p":26,"q":"Precipitation hardening, used for many nonferrous metals, works by:","o":["Rapid cooling to trap carbon atoms","Heat treatment causing alloying atoms to agglomerate in the lattice and block dislocations","Adding plasticisers","Hammering the metal"],"h":"The alloying element \"collects into a mass\".","a":1,"id":57},{"d":"wk02-engmaterials","p":27,"q":"The most industrially important strengthening mechanism in metals is:","o":["Solid solution strengthening","Precipitation hardening","Quench hardening","Mechanical working"],"h":"It involves rapid cooling and trapped solute atoms.","a":2,"id":58},{"d":"wk02-engmaterials","p":28,"q":"Metals are broadly divided into which two types?","o":["Crystalline and amorphous","Ferrous and nonferrous","Wrought and cast","Light and heavy"],"h":"Based on whether iron is the main element.","a":1,"id":59},{"d":"wk02-engmaterials","p":31,"q":"Iron-carbon alloys with less than 0.005% carbon at room temperature are classed as:","o":["Pure iron","Low carbon steel","Cast iron","Tool steel"],"h":"It is soft and used for magnetic devices and enamelling steels.","a":0,"id":60},{"d":"wk02-engmaterials","p":32,"q":"Steels are defined as iron–carbon alloys with carbon content approximately between:","o":["0.0005–0.005% C","0.006–0.06% C","0.06–2.0% C","More than 2.0% C"],"h":"Above about 2% C the alloys are cast irons.","a":2,"id":61},{"d":"wk02-engmaterials","p":32,"q":"Cast irons contain more than 2% carbon, and are usually shaped by casting because:","o":["They have very low melting points","The high carbon makes them too brittle for rolling, forming or shearing","They are too soft to machine","They cannot be melted"],"h":"Casting is about the only way to make a useful shape.","a":1,"id":62},{"d":"wk02-engmaterials","p":36,"q":"In the ore-to-steel process, limestone is a common flux used to:","o":["Add carbon to the iron","Remove silica","Cool the blast furnace","Coat the steel with zinc"],"h":"It combines with impurities to form slag.","a":1,"id":63},{"d":"wk02-engmaterials","p":42,"q":"In carbon steel, the principal hardening agent is:","o":["Manganese","Chromium","Carbon","Nickel"],"h":"Other elements are limited to small percentages.","a":2,"id":64},{"d":"wk02-engmaterials","p":43,"q":"In general usage, alloy steels are steels with total alloy additions of less than about:","o":["0.5%","5%","10.5%","20%"],"h":"Used primarily for structural applications.","a":1,"id":65},{"d":"wk02-engmaterials","p":44,"q":"Galvanized steel is:","o":["Zinc-coated steel, applied by hot dipping","Tin-coated steel","Chromium-plated steel","Steel with 10.5% chromium"],"h":"It often has paint-adhesion problems.","a":0,"id":66},{"d":"wk02-engmaterials","p":45,"q":"Galvannealed steel differs from galvanized steel because it:","o":["Has no zinc coating","Is heat treated after zinc coating, creating an oxide layer for better paint adhesion","Uses tin instead of zinc","Is cold rolled thinner"],"h":"Galvanized + annealed.","a":1,"id":67},{"d":"wk02-engmaterials","p":48,"q":"Tin plate is:","o":["Pure tin sheet","Cold-rolled steel, usually 0.1 to 0.4 mm thick, which may or may not be tin coated","Hot-rolled steel thicker than 6.4 mm","Zinc-coated steel"],"h":"Used for cans.","a":1,"id":68},{"d":"wk02-engmaterials","p":49,"q":"\"Free machining\" steels contain additions of:","o":["Chromium and nickel","Sulfur, lead, selenium or similar elements","Zinc by hot dipping","Extra carbon above 2%"],"h":"These make chips break easily.","a":1,"id":69},{"d":"wk02-engmaterials","p":50,"q":"Pickling is:","o":["Coating steel with zinc","Using acids to remove oxides and scale on hot-worked steels","Heat treating steel to improve paint adhesion","Quenching steel in brine"],"h":"A cleaning step after hot rolling.","a":1,"id":70},{"d":"wk02-engmaterials","p":52,"q":"Stainless steels have a minimum chromium content of:","o":["5%","8%","10.5%","18%"],"h":"Chromium forms the passive layer.","a":2,"id":71},{"d":"wk02-engmaterials","p":52,"q":"Which of the following is NOT one of the four major categories of wrought stainless steel?","o":["Austenitic","Ferritic","Martensitic","Pearlitic"],"h":"The fourth is precipitation hardening.","a":3,"id":72},{"d":"wk02-engmaterials","p":54,"q":"Grade 304 stainless steel is often called 18/8 because it contains:","o":["About 18% chromium and 8% nickel","About 18% nickel and 8% chromium","18% carbon and 8% chromium","18% chromium and 8% molybdenum"],"h":"It is austenitic and non-magnetic.","a":0,"id":73},{"d":"wk02-engmaterials","p":54,"q":"Grade 316 stainless steel has superior resistance to salt water compared to 304 mainly due to the addition of:","o":["Carbon","Zinc","Molybdenum","Lead"],"h":"Used in marine gear and surgical tools.","a":2,"id":74},{"d":"wk02-engmaterials","p":54,"q":"Austenitic grade 304 stainless steel is:","o":["Non-magnetic","Strongly magnetic","Hardenable by quenching","Used mainly for exhaust systems"],"h":"Kitchen sinks are typically 304.","a":0,"id":75},{"d":"wk02-engmaterials","p":55,"q":"Ferritic stainless steels are magnetic and are commonly used for:","o":["Surgical implants","Automotive exhaust systems and heat-transfer equipment","Cutlery and turbine blades","High-temper springs"],"h":"Moderate toughness and corrosion resistance.","a":1,"id":76},{"d":"wk02-engmaterials","p":57,"q":"Which stainless steels are magnetic, can be hardened by heat treatment, and are used for cutlery, bearings and moulds?","o":["Austenitic","Ferritic","Martensitic","Precipitation-hardening"],"h":"Strength/hardness is the primary concern.","a":2,"id":77},{"d":"wk02-engmaterials","p":58,"q":"Precipitation-hardening stainless steels are valued because they:","o":["Achieve very high strength through a low-temperature heat treatment that does not significantly distort precision parts","Are the cheapest stainless steels","Are non-magnetic food-grade steels","Cannot be heat treated"],"h":"Used for aircraft components and springs.","a":0,"id":78},{"d":"wk02-engmaterials","p":59,"q":"Tool steels are always ______ to develop their best properties.","o":["Galvanised","Heat treated","Pickled","Cold rolled"],"h":"They are high-alloy, metallurgically clean steels.","a":1,"id":79},{"d":"wk02-engmaterials","p":62,"q":"Which type of tool steel makes good cutting tools because it resists softening at high service temperatures?","o":["Type S (shock-resisting)","Type P (mold steels)","Type T/M (high-speed)","Type H (hot-work)"],"h":"Its name suggests fast cutting.","a":2,"id":80},{"d":"wk02-engmaterials","p":61,"q":"Shock-resisting tool steels (type S) are used for:","o":["Chisels, punches and shear blades","Plastic injection moulds","High-speed cutting tools","Airframe structures"],"h":"Strong and tough but less wear resistant.","a":0,"id":81},{"d":"wk02-engmaterials","p":62,"q":"Type P tool steels are created specifically for:","o":["Cutting tools","Plastic and die-cast tooling (moulds)","Pneumatic chisels","Springs"],"h":"P stands for plastic mould.","a":1,"id":82},{"d":"wk02-engmaterials","p":65,"q":"In powder metallurgy, compacting pressures are typically between:","o":["1 and 10 MPa","80 MPa and 1600 MPa","2000 and 5000 MPa","0.1 and 1 MPa"],"h":"The compacted part is then sintered.","a":1,"id":83},{"d":"wk02-engmaterials","p":68,"q":"In powder metallurgy, parts are formed by compaction and then:","o":["Melted and cast","Sintered","Anodised","Pickled"],"h":"Heating below the melting point bonds the particles.","a":1,"id":84},{"d":"wk02-engmaterials","p":69,"q":"Metal injection moulding (MIM) combines:","o":["The shaping capability of plastic injection moulding with the material flexibility of powder metallurgy","Die casting with forging","Sand casting with machining","Extrusion with rolling"],"h":"Ideal for small intricate parts like watch links.","a":0,"id":85},{"d":"wk02-engmaterials","p":69,"q":"MIM parts can achieve approximately what percentage of wrought material properties?","o":["50–60%","70–80%","95–98%","100–110%"],"h":"At a much reduced cost for small intricate parts.","a":2,"id":86},{"d":"wk02-engmaterials","p":75,"q":"Aluminium resists corrosion because:","o":["It contains chromium","A hard microscopic oxide coating forms on its surface when exposed to air","It is always painted","It is galvanized"],"h":"Its own anticorrosion mechanism.","a":1,"id":87},{"d":"wk02-engmaterials","p":75,"q":"Which of the following is NOT a property of aluminium given in the notes?","o":["High strength-to-weight ratio","Non-sparking","Nonmagnetic","Poor electrical conductivity"],"h":"It is used in power lines.","a":3,"id":88},{"d":"wk02-engmaterials","p":78,"q":"Brass is an alloy of copper and ______, while bronze is an alloy of copper and ______.","o":["zinc; tin","tin; zinc","nickel; tin","zinc; lead"],"h":"Bronze statues, brass plumbing fittings.","a":0,"id":89},{"d":"wk02-engmaterials","p":77,"q":"Which statement about copper is correct?","o":["It has a high strength-to-weight ratio","It has excellent electrical and thermal conductivity and corrosion resistance","It has high strength at elevated temperatures","It is the lightest structural metal"],"h":"Used for wires and pipes.","a":1,"id":90},{"d":"wk02-engmaterials","p":80,"q":"The lightest structural metal available is:","o":["Aluminium","Titanium","Magnesium","Zinc"],"h":"Used for power tool housings and racing wheels.","a":2,"id":91},{"d":"wk02-engmaterials","p":81,"q":"Magnesium alloys provide excellent dent resistance and a high:","o":["Thermal expansion","Damping capacity","Electrical resistance","Melting point"],"h":"They absorb energy elastically.","a":1,"id":92},{"d":"wk02-engmaterials","p":82,"q":"Because magnesium is sensitive to stress concentrations, designs should avoid:","o":["Thick sections","Notches, sharp corners and abrupt section changes","Large radii","Die casting"],"h":"Stress concentrators cause fatigue cracks.","a":1,"id":93},{"d":"wk02-engmaterials","p":83,"q":"Titanium has the highest tensile-strength-to-density ratio of any pure metal. Compared to steel it is:","o":["Stronger and twice as heavy","As strong but roughly 45% lighter","Weaker but 80% lighter","The same density"],"h":"Named after the Titans.","a":1,"id":94},{"d":"wk02-engmaterials","p":83,"q":"Titanium is ideal for medical implants mainly because it:","o":["Is the cheapest metal","Is non-toxic, biocompatible and highly corrosion resistant","Is magnetic","Has a low melting point"],"h":"It forms a protective oxide surface layer.","a":1,"id":95},{"d":"wk02-engmaterials","p":86,"q":"Zinc's excellent corrosion resistance leads to its use as:","o":["An alloying element in stainless steel","A coating for steel (galvanizing)","A filament material","Structural beams"],"h":"Zinc alloy is also popular for die casting.","a":1,"id":96},{"d":"wk02-engmaterials","p":89,"q":"Which one of the following is NOT a typical characteristic of polymers compared to metals?","o":["Long molecular chains with carbon backbones","Generally low thermal conductivity","High electrical conductivity","Generally lower strength and unsuitable for high-temperature use"],"h":"Polymers are often used as electrical insulators.","a":2,"id":97},{"d":"wk02-engmaterials","p":93,"q":"Polymers are classified in the notes into:","o":["Thermoplastics, thermosets and composites","Metals, ceramics and composites","Amorphous and crystalline only","Rubbers and fibres"],"h":"Composites here use a polymer matrix.","a":0,"id":98},{"d":"wk02-engmaterials","p":95,"q":"Thermoplastics can be classified into:","o":["Ferritic, austenitic and martensitic","Amorphous, crystalline and liquid crystalline polymers (LCP)","Random, alternating and block","Thermosets and elastomers"],"h":"Based on how ordered the polymer chains are.","a":1,"id":99},{"d":"wk02-engmaterials","p":96,"q":"Which of the following is an amorphous thermoplastic?","o":["Nylon","Polypropylene","Polycarbonate","Acetal"],"h":"Amorphous plastics can be intrinsically transparent.","a":2,"id":100},{"d":"wk02-engmaterials","p":96,"q":"Amorphous thermoplastics are characterised by:","o":["A broad softening point, consistent shrinkage and possible transparency","A sharp melting point and anisotropic shrinkage","Retaining order in the melt phase","No glass transition temperature"],"h":"Think of clear polycarbonate.","a":0,"id":101},{"d":"wk02-engmaterials","p":98,"q":"Thermosetting polymers are amorphous because:","o":["They have long slender chains","Crosslinking inhibits crystallisation","They are cooled quickly","They have no carbon backbone"],"h":"Their chains are tied together.","a":1,"id":102},{"d":"wk02-engmaterials","p":98,"q":"Thermosetting polymers, when heated above Tg:","o":["Melt into a liquid","Do not melt but will degrade","Recrystallise","Become transparent"],"h":"They cannot be remelted.","a":1,"id":103},{"d":"wk02-engmaterials","p":99,"q":"Which of the following is a crystalline thermoplastic?","o":["ABS","PVC","Polystyrene","Polypropylene"],"h":"Acetal, nylon, polyethylene, polyester are others.","a":3,"id":104},{"d":"wk02-engmaterials","p":100,"q":"Compared with amorphous thermoplastics, crystalline thermoplastics have:","o":["A broad softening range and intrinsic transparency","A sharp, higher melting point and anisotropic shrinkage/warpage","Lower chemical resistance","No melting point"],"h":"Organised chain packing.","a":1,"id":105},{"d":"wk02-engmaterials","p":99,"q":"Crystalline thermoplastics are stronger and stiffer than fully noncrystalline materials, but they are:","o":["More transparent","Less impact resistant","Less chemically resistant","Lower in melting temperature"],"h":"There is a trade-off.","a":1,"id":106},{"d":"wk02-engmaterials","p":103,"q":"Liquid crystalline polymers (LCPs) have the ______ shrinkage and warpage of the three types of thermoplastics.","o":["lowest","highest","same","most unpredictable"],"h":"They retain significant order in the melt phase.","a":0,"id":107},{"d":"wk02-engmaterials","p":105,"q":"Plasticizers are added to plastics to:","o":["Increase modulus and stiffness","Decrease modulus and increase flexibility","Increase electrical conductivity","Reduce UV yellowing"],"h":"Think of flexible PVC hose.","a":1,"id":108},{"d":"wk02-engmaterials","p":105,"q":"Particulate fillers such as silica, wood flour and glass balls are added to plastics to:","o":["Increase modulus, improve heat/UV resistance and reduce cost","Make the plastic transparent","Increase flexibility","Lower the melting temperature"],"h":"They also can increase electrical conductivity.","a":0,"id":109},{"d":"wk02-engmaterials","p":106,"q":"Aramid fibres are:","o":["Glass fibres","Aromatic polyamide fibres with high tensile strength","Carbon nanotubes","Natural plant fibres"],"h":"Kevlar is an example.","a":1,"id":110},{"d":"wk02-engmaterials","p":109,"q":"A copolymer contains:","o":["One monomer type only","Two different monomers","A physical mixture of two polymers","Three different repeating units"],"h":"Its properties may differ completely from the homopolymers.","a":1,"id":111},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with the arrangement -A-B-A-B-A-B- is a(n):","o":["Random copolymer","Alternating copolymer","Block copolymer","Graft copolymer"],"h":"Units alternate regularly.","a":1,"id":112},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with long runs like -A-A-A-A-B-B-B-B-A-A-A- is a:","o":["Random copolymer","Alternating copolymer","Block copolymer","Terpolymer"],"h":"Units come in blocks.","a":2,"id":113},{"d":"wk02-engmaterials","p":110,"q":"A copolymer with a main chain of A and side chains of B attached is a:","o":["Block copolymer","Random copolymer","Graft copolymer","Blend"],"h":"The B branches are \"grafted\" on.","a":2,"id":114},{"d":"wk02-engmaterials","p":111,"q":"Polymer blends (alloys) are made by:","o":["Chemically polymerising two monomers together","Physically mixing two or more polymers","Adding fillers to a resin","Crosslinking a thermoset"],"h":"Properties are usually intermediate between constituents.","a":1,"id":115},{"d":"wk02-engmaterials","p":113,"q":"ABS is an example of a:","o":["Homopolymer","Copolymer","Terpolymer","Thermoset"],"h":"It has three different repeating units.","a":2,"id":116},{"d":"wk02-engmaterials","p":113,"q":"ABS stands for:","o":["Acrylonitrile butadiene styrene","Acrylic butyl silicone","Amorphous blended styrene","Acetal butadiene styrene"],"h":"The B is a rubber that adds toughness.","a":0,"id":117},{"d":"wk02-engmaterials","p":114,"q":"ABS is tough because it contains microscopic particles of:","o":["Glass","Polybutadiene rubber","Carbon black","Silica"],"h":"The rubber phase absorbs impact.","a":1,"id":118},{"d":"wk02-engmaterials","p":118,"q":"For thin-walled injection moulded sections, the better choice is a:","o":["Lower-molecular-weight / lower-viscosity grade","Higher-molecular-weight / higher-viscosity grade","Thermoset grade","Glass-filled grade only"],"h":"It flows more easily into thin sections.","a":0,"id":119},{"d":"wk02-engmaterials","p":118,"q":"Higher-molecular-weight resin grades offer:","o":["Easier mould filling and faster cycles","Ultimate performance: tougher and more resistant to chemical attack","Lower viscosity","Lower cost"],"h":"Longer chains, stiffer flow.","a":1,"id":120},{"d":"wk02-engmaterials","p":121,"q":"Common problems from extended UV exposure of thermoplastics are:","o":["Increased stiffness and gloss","Colour shift and yellowing, plus possible loss of mechanical properties","Increased electrical conductivity","Crystallisation"],"h":"UV stabilisers are used to prevent this.","a":1,"id":121},{"d":"wk02-engmaterials","p":124,"q":"The hairline grooves on a moulded part where flow fronts join during filling are called:","o":["Sink marks","Weld lines (knit lines)","Flash","Short shots"],"h":"They can cut tensile strength by more than 50%.","a":1,"id":122},{"d":"wk02-engmaterials","p":125,"q":"Resins can suffer more than ____ loss of tensile strength at a weld line.","o":["5%","20%","50%","90%"],"h":"A significant drop.","a":2,"id":123},{"d":"wk02-engmaterials","p":126,"q":"Residual stresses in moulded thermoplastics are caused by:","o":["Uneven part cooling, differential shrinkage or frozen-in flow stresses","Adding UV stabilisers","Using a high-molecular-weight resin only","Using glass fillers"],"h":"They reduce impact strength and dimensional stability.","a":0,"id":124},{"d":"wk02-engmaterials","p":127,"q":"In injection moulding, mechanical properties are generally:","o":["Higher in the cross-flow direction","Lower in the cross-flow direction than in the flow direction","Identical in all directions","Only affected by mould temperature"],"h":"Polymer chains align with flow.","a":1,"id":125},{"d":"wk02-engmaterials","p":128,"q":"Fibre-filled materials generally have shrinkage in the cross-flow direction that is:","o":["Half that in the flow direction","Equal to the flow direction","2 to 3 times greater than in the flow direction","Zero"],"h":"Fibres align with flow and restrain shrinkage along it.","a":2,"id":126},{"d":"wk02-engmaterials","p":132,"q":"According to the polymer selection table, which polymer is \"usually white\"?","o":["ABS","Polycarbonate","Delrin (acetal)","Polystyrene"],"h":"It has good intricate design capability.","a":2,"id":127},{"d":"wk02-engmaterials","p":133,"q":"Lexan and Makrolon are trade names for:","o":["Polypropylene","Polycarbonate","LDPE","ABS"],"h":"A tough transparent amorphous plastic.","a":1,"id":128},{"d":"wk02-engmaterials","p":135,"q":"Ceramics are formed from a combination of:","o":["Two or more metals","One or more metals with a non-metallic element such as oxygen, nitrogen or carbon","Long carbon chains","A matrix and reinforcement"],"h":"Oxides, nitrides and carbides.","a":1,"id":129},{"d":"wk02-engmaterials","p":135,"q":"Ceramics typically have:","o":["High plasticity and low compressive strength","Very high compressive strength but poor plasticity","Good electrical conductivity","Low heat resistance"],"h":"They are brittle.","a":1,"id":130},{"d":"wk02-engmaterials","p":140,"q":"Composites are made from two or more materials, where one acts as the ______ to hold the ______.","o":["matrix; reinforcement","reinforcement; matrix","resin; filler","substrate; plasticiser"],"h":"Concrete holds steel bars.","a":0,"id":131},{"d":"wk02-engmaterials","p":141,"q":"Particulate composites such as cermets are typically:","o":["Light and flexible","Hard and abrasion resistant","Transparent","Highly ductile"],"h":"Used for cutting tools.","a":1,"id":132},{"d":"wk02-engmaterials","p":144,"q":"Epoxy resin in composites is noted for being:","o":["A transparent matrix when cured, used in aerospace","A reinforcement fibre","A thermoplastic substrate","Opaque and brittle only"],"h":"It acts as a structural glue.","a":0,"id":133},{"d":"wk02-engmaterials","p":144,"q":"In a common composite, fiberglass, carbon fibre and Kevlar serve as the:","o":["Resin","Substrate (reinforcement)","Matrix","Plasticiser"],"h":"Polyester and epoxy are the resins.","a":1,"id":134},{"d":"wk02-engmaterials","p":74,"q":"Which of the following are nonferrous metals?","o":["White cast iron, copper and stainless steel","Copper, aluminum and tin","Low carbon steel, white cast iron and tool steel","Silver, zinc and mild steel"],"h":"Nonferrous means iron is not the main constituent.","a":1,"id":135},{"d":"wk03-properties","p":4,"q":"How many major groups of properties are considered when selecting a material?","o":["3","4","6","8"],"h":"Physical, mechanical, technological, chemical, economic, aesthetic.","a":2,"id":136},{"d":"wk03-properties","p":5,"q":"Which of the following is primarily a technological property?","o":["Density","Tensile strength","Weldability","Corrosion resistance"],"h":"Technological properties describe behaviour during processing.","a":2,"id":137},{"d":"wk03-properties","p":4,"q":"Density, melting point and thermal conductivity are examples of:","o":["Physical properties","Mechanical properties","Technological properties","Economic properties"],"h":"Inherent aspects not easily altered.","a":0,"id":138},{"d":"wk03-properties","p":4,"q":"Hardness, toughness, creep resistance and fatigue resistance are:","o":["Physical properties","Mechanical properties","Chemical properties","Aesthetic properties"],"h":"They describe response to load.","a":1,"id":139},{"d":"wk03-properties","p":5,"q":"Resistance to oxidation, corrosion and solvents are classed as:","o":["Physical properties","Technological properties","Chemical properties","Economic properties"],"h":"Reactions with the environment.","a":2,"id":140},{"d":"wk03-properties","p":5,"q":"Machinability, castability, forgeability and brazeability are:","o":["Mechanical properties","Technological properties","Aesthetic properties","Physical properties"],"h":"How easily the material can be fabricated.","a":1,"id":141},{"d":"wk03-properties","p":5,"q":"Surface texture and the ability to accept special finishing are:","o":["Economic properties","Technological properties","Aesthetic properties","Chemical properties"],"h":"Appearance-related.","a":2,"id":142},{"d":"wk03-properties","p":3,"q":"Polyethylene is used as a wire coating material because of its:","o":["High thermal conductivity","Good electrical insulation and flexibility","High hardness","High density"],"h":"The copper inside conducts; the coating must insulate.","a":1,"id":143},{"d":"wk03-properties","p":8,"q":"Which statement best distinguishes physical from mechanical properties?","o":["Physical properties are generally not easily altered, whereas mechanical properties can be changed by heat treatment","Physical properties can be changed by heat treatment, mechanical cannot","Both are always fixed","Mechanical properties only apply to polymers"],"h":"Density stays put; hardness can be changed.","a":0,"id":144},{"d":"wk03-properties","p":8,"q":"Density is defined as:","o":["Weight per unit length","Mass / Volume","Volume / Mass","Load / Area"],"h":"Units g/cm3 or kg/m3.","a":1,"id":145},{"d":"wk03-properties","p":11,"q":"Thermal conductivity is expressed in units of:","o":["S/m","W/(m·K)","N/mm²","g/cm³"],"h":"Watts per metre-kelvin.","a":1,"id":146},{"d":"wk03-properties","p":12,"q":"Which material has the highest thermal conductivity at 25°C according to the notes?","o":["Silver (429 W/mK)","Copper (401 W/mK)","Aluminium (205 W/mK)","Cork board (0.07 W/mK)"],"h":"It edges out copper.","a":0,"id":147},{"d":"wk03-properties","p":13,"q":"Electrical conductivity is expressed in SI units of:","o":["Ohms","Siemens per metre (S/m)","W/mK","Volts per metre"],"h":"Copper is about 5.96 x 10^7 of these units.","a":1,"id":148},{"d":"wk03-properties","p":14,"q":"Relative to annealed copper (100), which metal has the highest relative electrical conductivity?","o":["Silver (106)","Gold (65)","Aluminium (63)","Steel (3-15)"],"h":"Silver is the best electrical and thermal conductor.","a":0,"id":149},{"d":"wk03-properties","p":15,"q":"Copper is chosen for wires inside electrical cables because it is an excellent conductor and is:","o":["Brittle","Ductile, so it can easily be drawn into long thin wires","Magnetic","Very hard"],"h":"Wire drawing requires a tensile-deformation property.","a":1,"id":150},{"d":"wk03-properties","p":16,"q":"Generally, the coefficient of thermal expansion is ______ to the melting point; ______ is a significant exception.","o":["inversely proportional; steel","directly proportional; aluminium","inversely proportional; copper","unrelated; glass"],"h":"Higher melt-temperature materials expand less.","a":0,"id":151},{"d":"wk03-properties","p":17,"q":"Ferromagnetism results from the alignment of which atoms into domains?","o":["Copper, zinc and tin","Iron, nickel and cobalt","Aluminium, magnesium and titanium","Gold, silver and platinum"],"h":"The three common magnetic metals.","a":1,"id":152},{"d":"wk03-properties","p":19,"q":"The three common forms of strength are:","o":["Tensile, compressive and shear","Tensile, hardness and fatigue","Elastic, plastic and creep","Impact, bending and torsion"],"h":"Pulling, pushing and sliding.","a":0,"id":153},{"d":"wk03-properties","p":19,"q":"Unit stress (σ) is defined as:","o":["Deformation per unit length","Applied load per unit area","Load per unit volume","Energy absorbed per unit area"],"h":"Expressed in N/mm² (MPa).","a":1,"id":154},{"d":"wk03-properties","p":20,"q":"Strain (ε) is expressed as:","o":["Load per unit area","Millimetre of deformation per millimetre of length","Newtons per metre","A percentage of mass"],"h":"It is dimensionless.","a":1,"id":155},{"d":"wk03-properties","p":22,"q":"Elasticity describes:","o":["Recovery of a material to its original shape and size after stress is removed","Permanent deformation without rupture","Resistance to scratching","Gradual deformation under sustained load"],"h":"A rubber band.","a":0,"id":156},{"d":"wk03-properties","p":23,"q":"When stretched bubble gum thins out and changes cross section, this is called:","o":["Creep","Necking","Spalling","Crazing"],"h":"It precedes fracture in ductile tensile tests.","a":1,"id":157},{"d":"wk03-properties","p":26,"q":"On a stress-strain curve, point A (end of the linear region) is called the:","o":["Tensile strength","Fracture point","Proportional or elastic limit","Lower yield point"],"h":"Below it, the material recovers fully.","a":2,"id":158},{"d":"wk03-properties","p":27,"q":"In practice, the \"yield point\" of a steel refers to the:","o":["Upper yield point","Lower yield point","Fracture point","Proportional limit"],"h":"Points B and C are the upper and lower yield points.","a":0,"id":159},{"d":"wk03-properties","p":28,"q":"On the stress-strain curve, the maximum stress before fracture (point D) is the:","o":["Yield strength","Proof stress","Tensile strength (UTS)","Elastic limit"],"h":"Fracture occurs later at point E.","a":2,"id":160},{"d":"wk03-properties","p":29,"q":"Which materials do NOT exhibit a marked yield point, but a smooth elastic-to-plastic transition?","o":["Mild steel","Cast iron and aluminium","Low carbon steel only","All ductile steels"],"h":"Mild steel shows a clear discontinuity.","a":1,"id":161},{"d":"wk03-properties","p":31,"q":"Proof stress is quoted to denote yield strength because:","o":["It is always higher than UTS","The yield point is often not apparent from practical testing","It measures hardness","It applies only to polymers"],"h":"Aluminium's curve has no obvious yield.","a":1,"id":162},{"d":"wk03-properties","p":32,"q":"The modulus of elasticity (E) is a measure of a material's:","o":["Hardness","Stiffness","Ductility","Toughness"],"h":"It is the slope of the linear part of the stress-strain curve.","a":1,"id":163},{"d":"wk03-properties","p":32,"q":"Plasticity is the ability of a material to:","o":["Recover its shape after load removal","Undergo permanent deformation without rupture","Resist penetration","Absorb impact energy"],"h":"Bubble gum stays deformed.","a":1,"id":164},{"d":"wk03-properties","p":33,"q":"Ultimate tensile strength is calculated by dividing the maximum load by the:","o":["Final cross-sectional area","Original cross-sectional area","Gauge length","Specimen volume"],"h":"It uses the starting dimensions.","a":1,"id":165},{"d":"wk03-properties","p":36,"q":"Concrete is used for building foundations because it has:","o":["Good compressive strength (though it is brittle)","High tensile strength","High ductility","Good torsional strength"],"h":"Foundations are squeezed, not pulled.","a":0,"id":166},{"d":"wk03-properties","p":37,"q":"In bending, the outside fibres of a beam are in ______ and the inside fibres in ______.","o":["tension; compression","compression; tension","shear; tension","torsion; compression"],"h":"The outer surface stretches.","a":0,"id":167},{"d":"wk03-properties","p":38,"q":"Crankshafts and propeller shafts must have superior:","o":["Compressive strength","Torsional strength","Hardness","Thermal conductivity"],"h":"They are twisted about their longitudinal axis.","a":1,"id":168},{"d":"wk03-properties","p":42,"q":"Ductility is the ability of a material to undergo plastic deformation by ______ without fracturing.","o":["tension","compression","scratching","impact"],"h":"Measured in a tensile test.","a":0,"id":169},{"d":"wk03-properties","p":45,"q":"Malleability differs from ductility because malleability is associated with:","o":["Tensile deformation","Compressive deformation","Elastic recovery","Scratch resistance"],"h":"Forging and rolling rely on it.","a":1,"id":170},{"d":"wk03-properties","p":45,"q":"Drawing a wire relies mainly on a material's:","o":["Ductility","Malleability","Hardness","Brittleness"],"h":"Wire is pulled through a die.","a":0,"id":171},{"d":"wk03-properties","p":46,"q":"Which metal is malleable but NOT ductile?","o":["Gold","Copper","Lead","Silver"],"h":"It can be hammered flat but tears when pulled.","a":2,"id":172},{"d":"wk03-properties","p":47,"q":"Hardness is the ability of a material to withstand:","o":["Twisting","Penetration, scratching or wear","Cyclic loading","High temperatures"],"h":"A ball bearing will dent clay but not glass.","a":1,"id":173},{"d":"wk03-properties","p":49,"q":"Which three hardness scales are most commonly used for engineering materials?","o":["Brinell, Vickers and Rockwell","Mohs, Knoop and Shore","Charpy, Izod and Brinell","Rockwell, Charpy and Scleroscope"],"h":"They are the first three in the list.","a":0,"id":174},{"d":"wk03-properties","p":51,"q":"Brittleness is the opposite of:","o":["Hardness","Ductility","Strength","Density"],"h":"A brittle material fractures with no plastic deformation.","a":1,"id":175},{"d":"wk03-properties","p":51,"q":"Which of the following are typical brittle materials?","o":["Mild steel, copper and gold","Hardened steels, cast irons and ceramics","Aluminium, lead and tin","Rubber and polyethylene"],"h":"Brittleness is associated with extreme hardness.","a":1,"id":176},{"d":"wk03-properties","p":51,"q":"Compared with mild steel, high tensile steel is:","o":["More brittle","More ductile","Softer","Lower in strength"],"h":"Brittleness is not related to tensile strength.","a":0,"id":177},{"d":"wk03-properties","p":52,"q":"Impact strength is associated with toughness, which depends mainly on:","o":["Hardness and colour","Ductility and strength","Density and melting point","Thermal and electrical conductivity"],"h":"Tough materials absorb energy before breaking.","a":1,"id":178},{"d":"wk03-properties","p":52,"q":"The two main forms of impact test are:","o":["Brinell and Vickers","Charpy and Izod","Rockwell and Knoop","Tensile and creep"],"h":"Both use a swinging pendulum.","a":1,"id":179},{"d":"wk03-properties","p":53,"q":"In the Izod impact test, the specimen is:","o":["Supported horizontally at both ends and struck behind the notch","Gripped vertically in a vice and struck just above the notch","Loaded in tension slowly","Indented with a diamond"],"h":"The Charpy specimen is horizontal.","a":1,"id":180},{"d":"wk03-properties","p":53,"q":"In the Charpy impact test, the specimen is:","o":["Supported freely at its ends horizontally and struck behind the notch at mid-span","Gripped vertically and struck above the notch","Twisted until failure","Indented with a steel ball"],"h":"It is a simply supported beam.","a":0,"id":181},{"d":"wk03-properties","p":54,"q":"In Charpy and Izod tests, the energy absorbed in breaking the specimen is measured by:","o":["The depth of the indentation","The difference in pendulum swing height before and after","The number of cycles to failure","The elongation of the specimen"],"h":"Some energy is used up breaking it.","a":1,"id":182},{"d":"wk03-properties","p":56,"q":"Failure caused by repeated or cyclic stressing below the tensile strength is called:","o":["Creep","Fatigue failure","Brittle fracture","Spalling"],"h":"Bending a wire back and forth.","a":1,"id":183},{"d":"wk03-properties","p":57,"q":"Which of the following is a typical example of fatigue failure?","o":["Connecting rods, crane hooks and aircraft bodies","Turbine blades under constant load at high temperature","Glass shattering when dropped","A wire being drawn"],"h":"These parts see repeated load cycles.","a":0,"id":184},{"d":"wk03-properties","p":59,"q":"Creep is best described as:","o":["Sudden fracture under impact at low temperature","Gradual plastic deformation under a sustained load, often at high temperature","Failure due to fluctuating stresses","Loss of strength due to UV"],"h":"Turbine blades and boiler tubes.","a":1,"id":185},{"d":"wk03-properties","p":62,"q":"Creep can also occur at room temperature, for example in:","o":["Glass windows","A milling machine table left in position under its own weight over time","A rubber band","Fasteners being tightened"],"h":"Prolonged service of structural beams.","a":1,"id":186},{"d":"wk03-properties","p":70,"q":"Materials selection is an interdependent consideration between which three basic elements?","o":["Product design, material and manufacture","Cost, colour and weight","Strength, hardness and toughness","Metals, polymers and ceramics"],"h":"Fig. 1 shows three linked circles.","a":0,"id":187},{"d":"wk03-properties","p":75,"q":"According to the general characteristics table, ceramics are:","o":["Weak, compliant and electrically insulating","Strong, stiff, tough and electrically conducting","Strong, brittle, durable, refractory and electrically insulating","Weak and temperature-sensitive"],"h":"Refractory means heat resisting.","a":2,"id":188},{"d":"wk03-properties","p":75,"q":"According to the general characteristics table, plastics are:","o":["Weak, compliant, durable, temperature-sensitive and electrically insulating","Strong, stiff and electrically conducting","Strong, brittle and refractory","Tough with high thermal conductivity"],"h":"They are soft and melt easily.","a":0,"id":189},{"d":"wk03-properties","p":76,"q":"An exception to the generalisation that metals are tough is that they:","o":["Are always ductile","Can be very brittle especially at low service temperatures","Cannot conduct heat","Degrade under UV"],"h":"Think of the Titanic's hull steel in icy water.","a":1,"id":190},{"d":"wk03-properties","p":79,"q":"Corrosion resistance, machinability and formability are examples of:","o":["Fundamental parameters","Ranking parameters","Physical constants","Design calculation inputs"],"h":"They can only rank materials in order of superiority.","a":1,"id":191},{"d":"wk03-properties","p":79,"q":"Fundamental parameters such as electrical resistivity have the advantage that they:","o":["Can be used directly in design calculations","Can only rank materials","Measure overall response to a process","Are always cheap to measure"],"h":"They measure basic properties.","a":0,"id":192},{"d":"wk03-properties","p":78,"q":"Weldability cannot be measured with a single parameter because:","o":["It is a physical property","It measures the overall response of a material to a particular process","It only applies to ceramics","It is purely aesthetic"],"h":"It is a ranking-type property.","a":1,"id":193},{"d":"wk03-properties","p":81,"q":"Which primary process is probably the most widely applicable?","o":["Forging","Machining","Casting","Powder metallurgy"],"h":"From 20 g zinc toys to 150-ton cast iron crushers.","a":2,"id":194},{"d":"wk03-properties","p":84,"q":"Injection moulding of polymers is described in the notes as essentially a:","o":["Forging process","Die casting process","Sintering process","Machining process"],"h":"Molten material is forced into a mould.","a":1,"id":195},{"d":"wk03-properties","p":85,"q":"Oxide ceramics, being brittle, must be formed by:","o":["Rolling and forging","Powder methods","Deep drawing","Extrusion of molten material"],"h":"Like sintering.","a":1,"id":196},{"d":"wk03-properties","p":87,"q":"Machining is usually a secondary process that:","o":["Follows a forming process but precedes joining and finishing","Precedes casting","Is the last step after painting","Replaces all forming processes"],"h":"It refines a formed part.","a":0,"id":197},{"d":"wk03-properties","p":88,"q":"Annealing is used to:","o":["Harden a metal by quenching","Remove the effects of cold work and soften a metal","Join ceramics","Coat steel with zinc"],"h":"The opposite of work hardening.","a":1,"id":198},{"d":"wk03-properties","p":88,"q":"The joining of ceramics is accomplished by:","o":["Arc welding","Soldering","Sintering","Riveting"],"h":"Same as how ceramic powders are consolidated.","a":2,"id":199},{"d":"wk03-properties","p":88,"q":"Which thermosets can be welded?","o":["All thermosets","Only those with a small amount of cross-linking","None at all under any conditions","Only fibre-reinforced thermosets"],"h":"Heavy crosslinking prevents melting.","a":1,"id":200},{"d":"wk03-properties","p":90,"q":"Porcelain is noted for its ability to:","o":["Resist almost all acids","Conduct electricity","Absorb water and swell","Be easily welded"],"h":"Ceramics are chemically stable.","a":0,"id":201},{"d":"wk03-properties","p":90,"q":"Although polymers are generally chemically stable, absorbed water will:","o":["Increase their conductivity","Change their properties and cause swelling","Harden them permanently","Make them transparent"],"h":"Nylon is a classic example.","a":1,"id":202},{"d":"wk03-properties","p":91,"q":"Ceramics are very stable at high temperatures, but under rapid temperature fluctuations they can suffer:","o":["Creep","Spalling","Necking","Depolymerisation"],"h":"Flakes break off from thermal shock.","a":1,"id":203},{"d":"wk03-properties","p":92,"q":"Heating can activate ______ in polymers, reducing performance.","o":["Crystallisation","Depolymerisation","Vulcanisation","Precipitation hardening"],"h":"Chains break down.","a":1,"id":204},{"d":"wk03-properties","p":93,"q":"Radiation damage in metals usually:","o":["Increases hardness and reduces ductility, similar to cold working","Softens the metal","Increases ductility","Causes swelling"],"h":"Annealing can reverse it.","a":0,"id":205},{"d":"wk03-properties","p":93,"q":"Commercial use has been made of UV radiation on polyethylene because it:","o":["Makes it transparent","Causes branching, increasing its stability at boiling-water temperature","Removes all crosslinks","Makes it conductive"],"h":"Radiation can have a beneficial effect.","a":1,"id":206},{"d":"wk03-properties","p":94,"q":"The total cost of a component considered in economic requirements includes:","o":["Only raw material cost","Raw material cost, fabrication cost and material availability","Only labour cost","Only shipping cost"],"h":"Availability affects completion date.","a":1,"id":207},{"d":"wk03-properties","p":95,"q":"The cost of a raw metallic material is often associated with:","o":["How plentiful its ore is","The complexity of extracting it from its ore and preparing it","Its colour","Its density"],"h":"Plentiful ore does not mean cheap.","a":1,"id":208},{"d":"wk03-properties","p":96,"q":"Using more expensive pre-hardened steels can reduce final cost because:","o":["It eliminates heat treatment and the resulting distortion","They are easier to cast","They need no machining at all","They are lighter"],"h":"A more expensive material may permit simpler processing.","a":0,"id":209},{"d":"wk04-casting","p":3,"q":"The three ways to form metals are:","o":["Liquid state, plastic state and solid state forming","Casting, moulding and printing","Hot, warm and cold forming","Primary, secondary and tertiary forming"],"h":"Classified by the state of the metal during forming.","a":0,"id":210},{"d":"wk04-casting","p":4,"q":"Casting is often the most economical way to manufacture:","o":["Thin flat sheets","A complex object, with metal placed where needed and minimal secondary operations","Long continuous profiles","Wire"],"h":"One of the earliest manufacturing processes.","a":1,"id":211},{"d":"wk04-casting","p":5,"q":"Problems associated with casting include a tendency toward:","o":["Porous structure and warpage","Work hardening","Excessive ductility","Anisotropic fibre orientation"],"h":"Gas and shrinkage cause defects.","a":0,"id":212},{"d":"wk04-casting","p":10,"q":"Wrought iron contains less than about ______ carbon, while cast iron contains ______ carbon.","o":["0.08%; 2.1% to 4%","2%; 6%","0.5%; 1%","0.005%; 0.06%"],"h":"Wrought iron is nearly pure iron with slag.","a":0,"id":213},{"d":"wk04-casting","p":10,"q":"The wood-like \"grain\" visible in wrought iron when etched or bent is due to:","o":["Graphite flakes","Fibrous slag inclusions","Carbon nodules","Dendrites"],"h":"Up to 2% by weight of slag.","a":1,"id":214},{"d":"wk04-casting","p":12,"q":"Cast irons are often melted in a:","o":["Blast furnace","Cupola","Electric arc crucible only","Kiln"],"h":"A continuous melter with alternating layers of coke.","a":1,"id":215},{"d":"wk04-casting","p":13,"q":"In a cupola furnace, charges of metal are melted in layers alternating with layers of fuel, usually:","o":["Charcoal","Coke","Natural gas","Wood"],"h":"Derived from coal.","a":1,"id":216},{"d":"wk04-casting","p":17,"q":"In sand casting, the cavity in the sand is formed using a(n):","o":["Pattern, an approximate duplicate of the real part, typically made of wood","Core","Riser","Sprue"],"h":"It is removed before pouring.","a":0,"id":217},{"d":"wk04-casting","p":17,"q":"In a sand casting mould, the box housing the aggregate is the:","o":["Cope","Drag","Flask","Core print"],"h":"It holds the sand.","a":2,"id":218},{"d":"wk04-casting","p":17,"q":"A sand shape inserted into the mould to produce internal features such as holes is a:","o":["Riser","Core","Pattern","Gate"],"h":"Internal passages.","a":1,"id":219},{"d":"wk04-casting","p":17,"q":"The region added to the pattern to locate and support the core within the mould is the:","o":["Riser","Runner","Core print","Parting line"],"h":"It holds the core in place.","a":2,"id":220},{"d":"wk04-casting","p":17,"q":"The purpose of a riser in sand casting is to:","o":["Form internal holes","Feed molten metal to the casting as it solidifies and shrinks, preventing voids","Locate the core","Separate cope and drag"],"h":"A reservoir of extra molten metal.","a":1,"id":221},{"d":"wk04-casting","p":18,"q":"In a two-part sand mould, the upper half is the ______ and the lower half is the ______.","o":["cope; drag","drag; cope","flask; core","riser; sprue"],"h":"\"Cope\" sits on top.","a":0,"id":222},{"d":"wk04-casting","p":18,"q":"The minimum draft angle usually applied to vertical surfaces of a sand casting pattern is:","o":["0°","1°","5°","10°"],"h":"It lets the pattern be removed without breaking the mould.","a":1,"id":223},{"d":"wk04-casting","p":18,"q":"Draft on a pattern is:","o":["A slight angular offset on vertical surfaces to allow pattern removal","A channel for metal flow","Extra metal to allow for shrinkage","The line separating cope and drag"],"h":"Usually at least 1°.","a":0,"id":224},{"d":"wk04-casting","p":19,"q":"There are how many major types of cast iron?","o":["3","5","7","9"],"h":"Gray iron is the oldest.","a":1,"id":225},{"d":"wk04-casting","p":21,"q":"The outstanding property of gray iron is its:","o":["High impact strength","Self-lubricating metal-to-metal wear characteristics","Ductility","Transparency"],"h":"Graphite flakes help it.","a":1,"id":226},{"d":"wk04-casting","p":21,"q":"Gray irons should be considered for machine parts that do NOT involve:","o":["Good machinability needs","Vibration damping needs","Shock loads, bending or high stresses","Wear"],"h":"It is brittle.","a":2,"id":227},{"d":"wk04-casting","p":23,"q":"Which cast iron is best suited for gears, cams and machine frames that may get an occasional shock load?","o":["Gray iron","Ductile (nodular) iron","White iron","Wrought iron"],"h":"It has as-cast strength higher than many mild steels.","a":1,"id":228},{"d":"wk04-casting","p":25,"q":"If many units are to be made, which cast alloy provides the best combination of machinability and stability?","o":["Gray iron","White iron","Malleable iron","Steel casting"],"h":"It is a special casting material for quantity parts.","a":2,"id":229},{"d":"wk04-casting","p":26,"q":"White iron is mainly used for:","o":["Abrasion resistance, such as hard rolls","Self-lubricating bearings","Shock-loaded gears","Decorative castings only"],"h":"A specialty wear material.","a":0,"id":230},{"d":"wk04-casting","p":27,"q":"Steel castings are used:","o":["As the first choice for all castings","After a designer is certain a cast iron will not do the job, for tough material problems","Only for decorative items","Only in die casting"],"h":"Cast irons are cheaper and easier to cast.","a":1,"id":231},{"d":"wk04-casting","p":30,"q":"During solidification, grains usually grow in a treelike form called a:","o":["Nucleus","Dendrite","Lattice","Spheroid"],"h":"From the Greek for tree.","a":1,"id":232},{"d":"wk04-casting","p":30,"q":"Which of the following is NOT one of the three major things that happen when a casting solidifies?","o":["Grains are formed","Melt chemistry changes during freezing","Shrinkage occurs","The metal is work hardened"],"h":"Work hardening comes from cold deformation.","a":3,"id":233},{"d":"wk04-casting","p":32,"q":"Turbine blades are directionally solidified in order to obtain:","o":["Fine equiaxed grains","Columnar grains in the long direction","An amorphous structure","Graphite nodules"],"h":"Usually columnar grains are undesirable, but not here.","a":1,"id":234},{"d":"wk04-casting","p":33,"q":"The major sources of casting defects are:","o":["Solidification porosity and shrinkage","Weld lines and residual stress","Springback and wrinkling","Flash and short shots"],"h":"Gas bubbles and voids.","a":0,"id":235},{"d":"wk04-casting","p":34,"q":"To minimise solidification shrinkage voids, the casting should be designed so that:","o":["The thickest section solidifies first","Gates and risers are the last areas to solidify","There are no risers","All sections solidify simultaneously"],"h":"Feed metal must stay liquid longest.","a":1,"id":236},{"d":"wk04-casting","p":35,"q":"In casting design, feed paths should be:","o":["As varied in cross section as possible","As uniform in cross-sectional area as possible","As long as possible","Avoided altogether"],"h":"Quality is built in at the design phase.","a":1,"id":237},{"d":"wk04-casting","p":39,"q":"Which casting process spins the mould, typically to produce cylindrical parts like cast-iron pipes?","o":["Investment casting","Centrifugal casting","Die casting","Shell moulding"],"h":"Centrifugal force pushes metal to the walls.","a":1,"id":238},{"d":"wk04-casting","p":41,"q":"Investment casting is also called:","o":["Lost wax, precision casting or solid mould casting","Shell moulding","Permanent mould casting","Slush casting"],"h":"The wax pattern is melted out.","a":0,"id":239},{"d":"wk04-casting","p":42,"q":"The plaster investment mould is typically composed of:","o":["100% silica sand","70-80% gypsum with 20-30% fibrous strengthening","Graphite and clay","Steel and bronze"],"h":"Plaster of Paris is gypsum.","a":1,"id":240},{"d":"wk04-casting","p":43,"q":"In investment casting, the cavity is formed when:","o":["A wooden pattern is pulled out","The flask is inverted and heated, melting the wax which drains out","The mould is machined","A core is removed"],"h":"The pattern is lost.","a":1,"id":241},{"d":"wk04-casting","p":43,"q":"Arrange the first steps of investment casting in order:","o":["Make a wax part, attach runners/sprue, pour investment, melt out wax","Pour metal, make wax part, melt wax, break mould","Pour investment, make wax, attach sprue, pour metal","Make sand mould, insert wax, pour metal, melt wax"],"h":"The wax comes first.","a":0,"id":242},{"d":"wk04-casting","p":49,"q":"Which of the following is an advantage of investment casting?","o":["Unlimited part size","Superior surface quality and thin, intricate sections with minimal draft","Lowest cost for large parts","Fastest cycle time"],"h":"Used for jewellery and medical instruments.","a":1,"id":243},{"d":"wk04-casting","p":49,"q":"The main disadvantage of investment casting is that it is:","o":["Rough in surface finish","Limited in size","Limited to plastics","Requiring large draft angles"],"h":"Seldom exceeds about 13 kg.","a":1,"id":244},{"d":"wk04-casting","p":47,"q":"Which process is described as similar to investment moulding and uses a resin-bonded shell?","o":["Sand casting","Shell moulding","Die casting","Centrifugal casting"],"h":"A typical part is an automobile camshaft.","a":1,"id":245},{"d":"wk04-casting","p":50,"q":"Permanent moulds are often made from gray cast iron because it has:","o":["The lowest cost of all metals","About the best thermal fatigue resistance","The highest melting point","Self-lubricating properties for ejection"],"h":"Moulds are heated and cooled repeatedly.","a":1,"id":246},{"d":"wk04-casting","p":50,"q":"Permanent mould castings are limited mainly to:","o":["Aluminium, zinc, some brass, bronze and lead","Steel and cast iron","Tungsten and molybdenum","Titanium only"],"h":"Low-melt-temperature nonferrous metals.","a":0,"id":247},{"d":"wk04-casting","p":50,"q":"Permanent moulds are usually coated with a ______ before being gravity filled.","o":["Zinc layer","Ceramic wash","Wax film","Oil"],"h":"Protects the mould from the molten metal.","a":1,"id":248},{"d":"wk04-casting","p":55,"q":"Die casting machines are classified as:","o":["Gravity and pressure","Hot chamber and cold chamber","Open and closed die","Single and double action"],"h":"Depends on where the metal is held.","a":1,"id":249},{"d":"wk04-casting","p":57,"q":"Die casting is limited mainly to:","o":["Ferrous metals and large parts","Nonferrous metals and fairly small parts","Ceramics","Thermosets"],"h":"Steel dies cannot withstand molten iron temperatures.","a":1,"id":250},{"d":"wk04-casting","p":57,"q":"Which is a disadvantage of die casting?","o":["Poor surface finish","Low production rates","Expensive tools, long lead time and required draft angles","Thick walls only"],"h":"Hardware is expensive.","a":2,"id":251},{"d":"wk04-casting","p":57,"q":"Typical applications of die casting include:","o":["Consumer electronics frames, automotive parts and motor housings","Large cast-iron pipes","Jewellery and sculpture","Ship propellers over 10 tons"],"h":"High volume nonferrous parts.","a":0,"id":252},{"d":"wk04-casting","p":52,"q":"The Herman Miller Equa chair by Chadwick and Stumpf is cited as an example of a product using several:","o":["Investment castings","Metal die castings","Sand castings","Forgings"],"h":"Aluminium components for furniture.","a":1,"id":253},{"d":"wk04-casting","p":58,"q":"Which of the following is NOT one of the six factors for evaluating a casting process?","o":["Tolerance","Surface finish","Size limitations","Colour of the alloy"],"h":"The others are materials, cost and availability.","a":3,"id":254},{"d":"wk04-casting","p":61,"q":"Shrinkage allowances for sand-cast metals range from about:","o":["0.1% to 0.5%","1% to 5%","10% to 15%","20% to 30%"],"h":"It depends on the alloy.","a":1,"id":255},{"d":"wk04-casting","p":62,"q":"Which casting process has the largest tolerances?","o":["Sand casting","Investment casting","Die casting","Permanent mould casting"],"h":"The least precise.","a":0,"id":256},{"d":"wk04-casting","p":62,"q":"Which casting process has the lowest tolerances of any casting process?","o":["Sand casting","Investment casting","Die casting","Centrifugal casting"],"h":"Unfortunately limited to nonferrous metals.","a":2,"id":257},{"d":"wk04-casting","p":62,"q":"Of the processes applicable to both ferrous and nonferrous metals, which has the lowest tolerances?","o":["Sand casting","Investment casting","Die casting","Centrifugal casting"],"h":"Die casting is nonferrous only.","a":1,"id":258},{"d":"wk04-casting","p":64,"q":"Which castings are very seldom good enough to allow attachment of other parts with a respectable fit?","o":["Die castings","Investment castings","Sand castings","Shell moulded castings"],"h":"Roughest surface.","a":2,"id":259},{"d":"wk04-casting","p":65,"q":"Die casting can produce parts weighing up to about:","o":["1 kg","18 kg","100 kg","No limit"],"h":"Investment castings seldom exceed 13 kg.","a":1,"id":260},{"d":"wk04-casting","p":65,"q":"Which casting process has no real limit to size?","o":["Die casting","Investment casting","Sand casting","Shell moulding"],"h":"From small items to 150-ton machines.","a":2,"id":261},{"d":"wk04-casting","p":65,"q":"Cast-iron pipes are usually produced by:","o":["Sand casting","Centrifugal casting","Die casting","Investment casting"],"h":"Lengths of 6 m and diameters up to 600 mm.","a":1,"id":262},{"d":"wk04-casting","p":66,"q":"Tungsten and molybdenum cause casting problems because of their:","o":["Low density","High melting temperatures","High ductility","Magnetic properties"],"h":"They melt above 2600°C.","a":1,"id":263},{"d":"wk04-casting","p":66,"q":"Die casting is seldom used for ferrous metals because:","o":["Steel die cavities cannot withstand the high molten metal temperatures","Ferrous metals are too fluid","Ferrous metals do not shrink","It produces too smooth a finish"],"h":"Expensive refractory moulds would be needed.","a":0,"id":264},{"d":"wk04-casting","p":69,"q":"If only a few castings are required, the cheapest process may be:","o":["Sand casting","Die casting","Permanent mould casting","Hot chamber die casting"],"h":"Low tooling cost.","a":0,"id":265},{"d":"wk04-casting","p":69,"q":"Investment casting tooling costs can often be amortised on as few as:","o":["5 castings","50 castings","5,000 castings","100,000 castings"],"h":"Castings are often ganged in one pour.","a":1,"id":266},{"d":"wk04-casting","p":69,"q":"Die casting is by far the fastest casting process, with cycle times as short as:","o":["10 seconds","1 minute","10 minutes","1 hour"],"h":"It needs thousands of parts to cover tooling cost.","a":0,"id":267},{"d":"wk04-casting","p":70,"q":"Typical lead times before the first part: sand casting ____, investment casting ____, die casting ____.","o":["1 month; 3 months; 6 months","1 week; 1 month; 3 months","3 months; 1 month; 6 months","6 months; 3 months; 1 month"],"h":"Die casting hardware takes longest.","a":0,"id":268},{"d":"wk04-casting","p":73,"q":"Ultimately, what should determine the choice between a casting or a fabrication (weldment or 3D print)?","o":["Personal preference only","Economics","Colour","Weight alone"],"h":"Cost comparisons from quotations.","a":1,"id":269},{"d":"wk04-casting","p":4,"q":"What is the primary production process for this fire hydrant?","o":["Forging","Casting","Machining from a block of steel","Sintering from powdered metal"],"h":"A complex, hollow iron shape is most economically made by pouring metal into a mould.","i":"img/hydrant.jpg","a":1,"id":270},{"d":"wk05-forming","p":4,"q":"Plastic state forming is a forming operation on solid metal at:","o":["Room temperature only","Elevated temperature, but below the critical or melt temperature","Above the melting point","Cryogenic temperature"],"h":"The metal is soft but not molten.","a":1,"id":271},{"d":"wk05-forming","p":4,"q":"Besides shaping the metal, the objective of plastic state forming is to:","o":["Control the grain structure so that the strength of the part is enhanced","Increase porosity","Produce a random grain structure","Remove all alloying elements"],"h":"Grain flow matters.","a":0,"id":272},{"d":"wk05-forming","p":8,"q":"When an \"S\" shaped bar is forged, its grain structure:","o":["Is random, as in casting","Runs horizontally, cut through by the shape","Follows the shape, which is superior in countering stress","Disappears completely"],"h":"One of the main benefits of forging.","a":2,"id":273},{"d":"wk05-forming","p":6,"q":"An S-shaped bar made by casting is weaker because:","o":["Its grain structure is random and cracks can develop along grain boundaries","Its grain follows the shape","It is work hardened","It has no grain boundaries"],"h":"Non-uniform walls also create stress concentrations.","a":0,"id":274},{"d":"wk05-forming","p":7,"q":"An S-shape cut from a rolled slab is poor in terms of stress because:","o":["The grain follows the shape","The cut runs through the horizontal grain of the slab","The grain is random","Rolling removes all grains"],"h":"Crack potential is nearly as great as casting.","a":1,"id":275},{"d":"wk05-forming","p":12,"q":"Hammer and drop forging shape the workpiece using:","o":["Near-instantaneous impact force (milliseconds)","Slow continuous pressure over seconds","Rotating dies only","Fluid pressure through a membrane"],"h":"A dropping weight.","a":0,"id":276},{"d":"wk05-forming","p":13,"q":"Press forging differs from drop forging because it:","o":["Uses impact in milliseconds","Applies a slow continuous pressure, with die contact measured in seconds","Is always done cold","Melts the workpiece"],"h":"A hydraulic cylinder provides force.","a":1,"id":277},{"d":"wk05-forming","p":14,"q":"Upset forging:","o":["Increases the diameter of the workpiece by compressing its length","Reduces the diameter by hammering with rotary dies","Pulls a rod through a die","Forces a billet through a die opening"],"h":"Used for bolt heads.","a":0,"id":278},{"d":"wk05-forming","p":14,"q":"Based on number of pieces produced, the most widely used forging process is:","o":["Drop forging","Press forging","Upset forging","Swaging"],"h":"Bolts, screws, engine valves.","a":2,"id":279},{"d":"wk05-forming","p":14,"q":"Upset forging is usually done in special high-speed machines called:","o":["Press brakes","Crank presses","Lathes","Cupolas"],"h":"A crank drives the ram.","a":1,"id":280},{"d":"wk05-forming","p":16,"q":"Swaging (rotary swaging / radial forging) uses two or more dies to:","o":["Increase the diameter of a bar","Hammer a round workpiece into a smaller diameter","Bend tubes over a mandrel","Spin a disc into a cup"],"h":"Think tapered tube ends.","a":1,"id":281},{"d":"wk05-forming","p":17,"q":"During rolling, the rollers must be water-cooled because:","o":["The metal must stay below 0°C","The process causes stress and friction which generates heat","Water lubricates the grains","It prevents corrosion"],"h":"Even \"cold\" rolling gets hot.","a":1,"id":282},{"d":"wk05-forming","p":18,"q":"In hot rolling, as the grains regrow during recovery, the result is:","o":["A coarse or rough surface","A smooth fine surface","An amorphous structure","A mirror finish"],"h":"Compare with cold rolling.","a":0,"id":283},{"d":"wk05-forming","p":19,"q":"Cold rolling a previously hot-rolled sheet yields:","o":["A coarse surface and lower cost","A smooth, fine surface, but increases cost by about 20%","A porous structure","No change in grain size"],"h":"The grains are smaller after annealing.","a":1,"id":284},{"d":"wk05-forming","p":23,"q":"In extrusion, a heated billet is:","o":["Pulled through a die","Forced through a die by a hydraulic ram to form a long profile","Hammered between two dies","Rolled between rollers"],"h":"Like squeezing toothpaste.","a":1,"id":285},{"d":"wk05-forming","p":24,"q":"Extruded profiles can be:","o":["Only solid","Only hollow","Solid, semi-hollow or hollow","Only round"],"h":"Window frames and heat sinks.","a":2,"id":286},{"d":"wk05-forming","p":25,"q":"Extrusions have revolutionised design partly because:","o":["Most extrusion materials and dies are relatively inexpensive","They require no dies","They can produce varying cross sections","They are only used for steel"],"h":"Virtually any profile is possible.","a":0,"id":287},{"d":"wk05-forming","p":23,"q":"The aluminium part below can be economically produced by:","o":["Investment casting","Die casting","Machining processes","Metal extrusion"],"h":"A long constant profile.","i":"img/extrusion.jpg","a":3,"id":288},{"d":"wk05-forming","p":22,"q":"In wire and rod drawing, the material is:","o":["Pulled through a die to reduce its diameter","Pushed through a die by a ram","Hammered by rotary dies","Rolled into sheets"],"h":"Relies on ductility.","a":0,"id":289},{"d":"wk05-forming","p":31,"q":"Solid state forming is the shaping of metal sheet, rod, wire or tube usually at:","o":["Above melting point","Just below critical temperature","Room temperature","Cryogenic temperature"],"h":"Heating is only sometimes required.","a":2,"id":290},{"d":"wk05-forming","p":31,"q":"A metal sheet is defined as ______ thick, while a metal plate is ______ thick.","o":["less than 6 mm; more than 6 mm","less than 1 mm; more than 1 mm","less than 12 mm; more than 12 mm","less than 3 mm; more than 25 mm"],"h":"The dividing thickness is 6 mm.","a":0,"id":291},{"d":"wk05-forming","p":32,"q":"During solid state forming, some metals can become brittle and may require ______ before forming continues.","o":["Quenching","Annealing","Galvanising","Pickling"],"h":"Softening heat treatment.","a":1,"id":292},{"d":"wk05-forming","p":33,"q":"In very high volume sheet operations with progressive, transfer or multiple-action dies that cut and form, the process is often called:","o":["Spinning","Stamping","Hydroforming","Swaging"],"h":"Also used generally for sheet forming.","a":1,"id":293},{"d":"wk05-forming","p":39,"q":"When bending tubes, an internal support called a ______ is used to prevent buckling.","o":["Core","Mandrel","Riser","Punch"],"h":"It is inserted inside the tube.","a":1,"id":294},{"d":"wk05-forming","p":40,"q":"The classic 1927 bent-tube chair that set the standard for modern furniture is the:","o":["Equa chair","Wassily chair","Barcelona chair","Panton chair"],"h":"Designed by Marcel Breuer.","a":1,"id":295},{"d":"wk05-forming","p":41,"q":"In the Wassily chair, Breuer's bending limitations became an aesthetic through:","o":["Consistent bend radii giving a sense of order and unity","Sharp mitred corners","Varying tube diameters","Hidden welded joints"],"h":"Tube bending has a minimum radius.","a":0,"id":296},{"d":"wk05-forming","p":45,"q":"Bending thermoplastic sheet is similar to bending sheet metal but requires:","o":["A mandrel","Localised heating to soften the sheet at the bend","A matched die set","Quenching after bending"],"h":"Strip heaters are used.","a":1,"id":297},{"d":"wk05-forming","p":47,"q":"Air bending is also known as:","o":["Wipe bending","Three-point bending","V-die bending","Roll bending"],"h":"Two support points and a punch.","a":1,"id":298},{"d":"wk05-forming","p":47,"q":"Compared with V-die bending, air bending:","o":["Is cheaper but less accurate","Is more expensive and more accurate","Uses a matched punch and die","Cannot bend steel"],"h":"Eliminating the die reduces cost.","a":0,"id":299},{"d":"wk05-forming","p":48,"q":"The most expensive bending operation, using a matched punch and die designed for a particular application, is:","o":["Air bending","V-die bending","Brake bending","Roll bending"],"h":"It produces very accurate bends.","a":1,"id":300},{"d":"wk05-forming","p":49,"q":"An inexpensive bending tool often found in small model shops, with radius attachments, is the:","o":["V-die","Brake (wiping die)","Progressive die","Hydroform press"],"h":"It wipes the sheet over an edge.","a":1,"id":301},{"d":"wk05-forming","p":51,"q":"Continuous roll forming produces profiles somewhat like extrusions, except that:","o":["The profile is limited to the original thickness of the sheet","It can only make short parts","It requires molten metal","It produces hollow sections only"],"h":"Sheet from a coil passes through rollers.","a":0,"id":302},{"d":"wk05-forming","p":51,"q":"A disadvantage of continuous roll forming is:","o":["Uneconomical at high volume","Limited length","Uniform profile thickness only and large minimum orders","Cannot form galvanized steel"],"h":"2 m to 3000 m minimum order.","a":2,"id":303},{"d":"wk05-forming","p":53,"q":"Spinning is commonly used to produce:","o":["Symmetrical cuplike shapes or frisbee-shaped discs","Long constant profiles","Box-shaped enclosures with sharp corners","Wire frames"],"h":"The sheet is forced onto a pattern on a special lathe.","a":0,"id":304},{"d":"wk05-forming","p":55,"q":"Metal spinning is labour intensive but its dies (patterns) are:","o":["Very expensive","Inexpensive","Made only from ceramics","Not required"],"h":"Often wooden patterns.","a":1,"id":305},{"d":"wk05-forming","p":57,"q":"In hydroforming, a flexible membrane sealing a fluid-filled cavity:","o":["Eliminates the need for a matching die cavity","Melts the workpiece","Replaces the punch","Cuts the sheet"],"h":"Fluid pressure acts as the female die.","a":0,"id":306},{"d":"wk05-forming","p":57,"q":"Hydroforming was developed in the late 1940s and early 1950s for:","o":["Very high volumes of shallow parts","Lower cost production of relatively small quantities of deep drawn parts","Casting turbine blades","Making wire"],"h":"Avoids an expensive matched die.","a":1,"id":307},{"d":"wk05-forming","p":59,"q":"A notable product example of hydroforming shown in the notes is:","o":["A wine bottle","A bicycle frame","A bolt","A cast-iron pipe"],"h":"Tubes expanded with fluid pressure.","a":1,"id":308},{"d":"wk05-forming","p":60,"q":"In drawing, sheet metal is formed into hollow shapes by:","o":["A punch that forces the metal into a matching die cavity","Spinning it on a lathe","Squeezing it between rollers","Fluid pressure alone"],"h":"Think of a drink can.","a":0,"id":309},{"d":"wk05-forming","p":62,"q":"In deep drawing, the depth of the hollow is:","o":["Less than half the diameter","Equal to the thickness","Two or more times the diameter","Always ten times the diameter"],"h":"Normally done in successive steps.","a":2,"id":310},{"d":"wk05-forming","p":65,"q":"A simple die:","o":["Performs one action, such as bending or punching, at one time","Performs many operations at multiple stations simultaneously","Uses fluid pressure","Is used only for spinning"],"h":"The part is moved to another station afterwards.","a":0,"id":311},{"d":"wk05-forming","p":68,"q":"Which is NOT a characteristic of progressive die stamping?","o":["Multiple cutting/forming operations simultaneously","Well suited to small parts at a rapid rate","Requires expensive die sets","Ideal for very low volume prototypes"],"h":"High investment needs high volume.","a":3,"id":312},{"d":"wk05-forming","p":72,"q":"Deep draw stamping allows metal to be drawn to a ratio of about:","o":["1 to 1","2 to 1","7 or 8 to 1","20 to 1"],"h":"Progressive dies are normally limited to shallow draws.","a":2,"id":313},{"d":"wk05-forming","p":70,"q":"In progressive die stamping, the metal strip:","o":["Moves through a series of die stations, each changing the configuration from the previous one","Is spun on a lathe","Is cast into a die","Is extruded through a single die"],"h":"The part is created in stages.","a":0,"id":314},{"d":"wk05-forming","p":31,"q":"Heating may be required in solid state forming if the metal:","o":["Is thin","Is thick, not very ductile, or becomes work hardened","Is aluminium","Is to be painted"],"h":"Normally done at room temperature.","a":1,"id":315},{"d":"wk06-thermoplastics","p":4,"q":"Probably the most limiting factor in applying plastics to a new design is their:","o":["Colour range","Fabricability","Density","Electrical insulation"],"h":"Whether it can actually be made into the shape.","a":1,"id":316},{"d":"wk06-thermoplastics","p":4,"q":"PTFE (Teflon) parts can only be made by:","o":["Injection moulding","Blow moulding","Sintering particles together under significant pressure","Thermoforming"],"h":"This plus high cost limits its use.","a":2,"id":317},{"d":"wk06-thermoplastics","p":5,"q":"Continuous fibre-reinforced plastics have higher stiffness and strength, but:","o":["The processes to add continuous fibres are limited and none are as low cost as injection moulding for many parts","They cannot be coloured","They are weaker than unreinforced plastics","They can only be extruded"],"h":"Fabrication options limit their use.","a":0,"id":318},{"d":"wk06-thermoplastics","p":7,"q":"Thermoplastic materials are those plastics that:","o":["Can be re-melted and reused","Cannot be remelted once cured","Are always crosslinked","Are only formed by casting"],"h":"Unlike thermosets.","a":0,"id":319},{"d":"wk06-thermoplastics","p":13,"q":"What are the six major steps of the injection moulding process, in order?","o":["Injection, clamping, cooling, dwelling, ejection, mould opening","Clamping, injection, dwelling, cooling, mould opening, ejection","Drying, injection, clamping, ejection, cooling, opening","Clamping, cooling, injection, dwelling, ejection, opening"],"h":"The mould must be closed first.","a":1,"id":320},{"d":"wk06-thermoplastics","p":13,"q":"In injection moulding, the \"dwelling\" step:","o":["Opens the mould","Holds pressure after injection to pack the cavity","Ejects the part","Dries the resin"],"h":"It comes right after injection.","a":1,"id":321},{"d":"wk06-thermoplastics","p":12,"q":"Before injection, plastic granules typically go through:","o":["Mixing and blending, drying, and machine feeding","Sintering and pressing","Calendering and cooling","Parison extrusion"],"h":"Moisture must be removed.","a":0,"id":322},{"d":"wk06-thermoplastics","p":18,"q":"Bi-injection (two-shot) moulding is often done to:","o":["Make hollow bottles","Achieve a cosmetic effect or alter use properties","Make large tanks","Form thin film"],"h":"e.g. a toothbrush handle with a soft grip.","a":1,"id":323},{"d":"wk06-thermoplastics","p":20,"q":"Co-injection moulding is used to achieve:","o":["A sandwich effect with a different polymer core inside a skin","Two colours side by side","A hollow part","A foam outer layer"],"h":"The core can be recycled material.","a":0,"id":324},{"d":"wk06-thermoplastics","p":20,"q":"Which is a cost-saving use of co-injection?","o":["Injecting a premium core inside a cheap skin","Injecting an inexpensive (e.g. recycled) core into a premium skin","Removing the need for a mould","Eliminating the cooling step"],"h":"The visible skin is premium.","a":1,"id":325},{"d":"wk06-thermoplastics","p":26,"q":"Which is an advantage of injection moulding?","o":["High production rates with repeatable high tolerances and minimal scrap","Low equipment investment","No design constraints on parts","Ideal for one-off parts"],"h":"Low labour costs too.","a":0,"id":326},{"d":"wk06-thermoplastics","p":26,"q":"Which is a disadvantage of injection moulding?","o":["Low production rate","High scrap losses","Expensive equipment investment","Extensive finishing required"],"h":"Moulds and machines cost a lot.","a":2,"id":327},{"d":"wk06-thermoplastics","p":27,"q":"A variation of injection moulding that produces parts with a foamed core and solid skin is:","o":["Rotational moulding","Structural foam moulding","Calendering","Thermoforming"],"h":"Used for thick, rigid lightweight parts.","a":1,"id":328},{"d":"wk06-thermoplastics","p":30,"q":"Plastic bottles such as shampoo bottles with a handle are commonly made by:","o":["Extrusion blow moulding","Injection moulding","Rotational moulding","Calendering"],"h":"A parison is extruded and inflated.","a":0,"id":329},{"d":"wk06-thermoplastics","p":35,"q":"In blow moulding, compressed air is blown into a(n) ______ so that it takes the shape of the mould walls.","o":["Billet","Parison","Preform sheet","Calendered film"],"h":"A hollow tube of molten plastic.","a":1,"id":330},{"d":"wk06-thermoplastics","p":32,"q":"Stretch blow moulding is noted for:","o":["Low volume production only","Superior visual and dimensional quality, fully finished with no flash","Making large water tanks","Producing flat sheets"],"h":"Used for PET soft drink bottles.","a":1,"id":331},{"d":"wk06-thermoplastics","p":36,"q":"Two-litre soft drink bottles are typically made from which lightweight, transparent, shatter-resistant plastic?","o":["PVC","Polystyrene","PET (polyethylene terephthalate)","ABS"],"h":"Coatings can extend shelf life.","a":2,"id":332},{"d":"wk06-thermoplastics","p":37,"q":"Calendering forms sheet or film by:","o":["Passing material through a series of heated rolls","Forcing molten polymer through a die","Spinning a mould in an oven","Vacuum drawing a sheet over a mould"],"h":"Used for vinyl flooring tiles.","a":0,"id":333},{"d":"wk06-thermoplastics","p":37,"q":"Which products are often formed by calendering?","o":["Fuel tanks and boat hulls","Elastomer sheets, gaskets and vinyl flooring tiles","Bottles","Door bell casings"],"h":"Flat sheet products.","a":1,"id":334},{"d":"wk06-thermoplastics","p":40,"q":"Calendering of film is preferably used for:","o":["Short runs","Long runs, e.g. decorative flooring sheets and stretch wrap","One-off prototypes","Hollow parts"],"h":"Precision thin sheet production.","a":1,"id":335},{"d":"wk06-thermoplastics","p":41,"q":"In the tubular film process (film blowing), after melting and cooling, further heating is used for:","o":["Crosslinking","Axial stretching of the film","Adding a core","Calendering"],"h":"Plastic bags are made this way.","a":1,"id":336},{"d":"wk06-thermoplastics","p":43,"q":"Rotational moulding is usually used for:","o":["Small precision gears","Large hollow containers such as fuel tanks, water tanks and boat hulls","Thin films","Bottles at very high speed"],"h":"The mould rotates in an oven.","a":1,"id":337},{"d":"wk06-thermoplastics","p":43,"q":"Rotational moulding tooling is less expensive because:","o":["There is no internal core and moulds need not withstand high pressure","Moulds are made of paper","It uses thermosets only","It needs no heating"],"h":"Parts form by heat and rotation, not pressure.","a":0,"id":338},{"d":"wk06-thermoplastics","p":44,"q":"In rotational moulding, material is pushed to the cavity walls by:","o":["Compressed air","A plunger","Centrifugal force as the heated mould rotates","Vacuum"],"h":"Then cooled for final setting.","a":2,"id":339},{"d":"wk06-thermoplastics","p":49,"q":"Solid-phase forming heats a thermoplastic sheet or preform to:","o":["Above its melting point","Its softening point, but below the melting point","Room temperature only","Its decomposition temperature"],"h":"It stays solid but pliable.","a":1,"id":340},{"d":"wk06-thermoplastics","p":55,"q":"Thermo vacuum forming draws a heated sheet into the shape of the mould using:","o":["Compressed air from inside","Heat and negative pressure (vacuum)","A matched metal die at high pressure","Centrifugal force"],"h":"Low tooling costs.","a":1,"id":341},{"d":"wk06-thermoplastics","p":55,"q":"Which is an advantage of vacuum forming?","o":["Economical for small to medium runs with low tooling cost and quick startup","Best for very thick solid parts","Produces hollow closed containers","Requires the most expensive equipment of all processes"],"h":"Good for prototyping.","a":0,"id":342},{"d":"wk06-thermoplastics","p":58,"q":"Plastic extrusion forms continuous shapes by:","o":["Passing sheets through heated rolls","Forcing molten polymer through a metal die","Blowing a parison","Sintering powder"],"h":"Used for weather stripping.","a":1,"id":343},{"d":"wk06-thermoplastics","p":58,"q":"Specially shaped weather stripping is typically made by:","o":["Injection moulding","Extrusion","Rotational moulding","Thermoforming"],"h":"Continuous constant profile.","a":1,"id":344},{"d":"wk06-thermoplastics","p":61,"q":"3D printing builds physical objects from digital models by:","o":["Adding material one ultra-thin layer at a time","Removing material by cutting","Forcing material through a die","Spinning a mould"],"h":"Additive manufacturing.","a":0,"id":345},{"d":"wk06-thermoplastics","p":63,"q":"An injection moulding, blow moulding or film blowing machine can easily cost more than:","o":["$1,000","$10,000","$100,000","$10,000,000"],"h":"High equipment cost is why vendors specialise.","a":2,"id":346},{"d":"wk06-thermoplastics","p":63,"q":"Which thermoplastic process can be done with very simple equipment like wooden forms, a vacuum cleaner and an oven?","o":["Injection moulding","Blow moulding","Thermoforming","Calendering"],"h":"Heat a sheet and suck it down.","a":2,"id":347},{"d":"wk06-thermoplastics","p":9,"q":"A door bell casing made from ABS would most likely be produced by:","o":["Blow moulding","Injection moulding","Calendering","Rotational moulding"],"h":"A small, detailed, high-volume part.","a":1,"id":348},{"d":"wk06-thermoplastics","p":6,"q":"When selecting a plastic, which fabrication question is relevant?","o":["Is it ferromagnetic?","Does it have a high or low shrinkage rate in moulding?","What is its Mohs hardness?","Can it be galvanised?"],"h":"Consider fabrication options with the plastic.","a":1,"id":349},{"d":"wk07-thermosets","p":4,"q":"The first completely man-made thermosetting plastic, discovered by Leo Baekeland in 1907, is:","o":["Urea formaldehyde","Phenol formaldehyde (Bakelite)","Polyester","Epoxy"],"h":"Trade name Bakelite.","a":1,"id":350},{"d":"wk07-thermosets","p":4,"q":"True Bakelite (phenolic) mouldings are limited to:","o":["Bright colours and white","Black and dark shades of brown, green, red and rarer blue","Transparent grades only","Pastel colours"],"h":"Urea formaldehyde later allowed brighter colours.","a":1,"id":351},{"d":"wk07-thermosets","p":5,"q":"The GPO Telephone No.162 (1935) was notable as the first:","o":["All-plastic telephone, made from phenol formaldehyde","Injection moulded ABS telephone","Rotationally moulded product","Wireless phone"],"h":"An iconic Bakelite product.","a":0,"id":352},{"d":"wk07-thermosets","p":6,"q":"Urea formaldehyde, developed by British Cyanides in 1925, improved on phenolic by allowing:","o":["Higher heat resistance","Bright colours and more decorative patterns","Remelting","Transparency"],"h":"Bakelite was restricted to dark colours.","a":1,"id":353},{"d":"wk07-thermosets","p":9,"q":"Liquid thermoset resin systems such as epoxy require:","o":["Only cooling to solidify","Two or more components (resin and hardener) to be mixed to initiate crosslinking","Remelting in an extruder","Sintering"],"h":"e.g. a bisphenol A resin plus a polyamide hardener.","a":1,"id":354},{"d":"wk07-thermosets","p":12,"q":"Why are thermosets often moulded in simpler equipment than thermoplastics?","o":["Once formed they cannot be remelted, making machine cleanout very difficult","They need higher pressures","They are always liquid","They cannot be heated"],"h":"A thermoset curing in a barrel can fuse the screw in place.","a":0,"id":355},{"d":"wk07-thermosets","p":14,"q":"In compression moulding, the preheated, premeasured material is:","o":["Injected through a gate into a closed mould","Placed in an open mould cavity, then the mould is closed and heat and pressure applied until it cures","Poured without pressure","Sprayed onto a mould"],"h":"Like making a waffle.","a":1,"id":356},{"d":"wk07-thermosets","p":16,"q":"The most widely used process for thermosetting materials is:","o":["Injection moulding","Compression moulding","Blow moulding","Calendering"],"h":"Cycle times are longer than injection moulding.","a":1,"id":357},{"d":"wk07-thermosets","p":16,"q":"Compression moulding cycle times for thermosets are much longer than injection moulding because:","o":["The moulds are larger","Curing of thermosets is a time-dependent reaction","The material must be cooled to room temperature","The press is slower"],"h":"Crosslinking takes time.","a":1,"id":358},{"d":"wk07-thermosets","p":17,"q":"Thermoset injection moulding cycles are how much faster than compression moulding?","o":["The same","2 to 3 times faster","10 times faster","Slower"],"h":"Yielding lower cost parts.","a":1,"id":359},{"d":"wk07-thermosets","p":18,"q":"In thermoset injection moulding, the polymer is injected when:","o":["Its viscosity is at its lowest level, after heating","It has fully crosslinked","It is completely cold","It is a solid pellet"],"h":"Viscosity then increases as it cross-links in the mould.","a":0,"id":360},{"d":"wk07-thermosets","p":18,"q":"After ejection in thermoset injection moulding, parts may be:","o":["Remelted","Post-heated in an oven to ensure complete curing","Quenched in water","Vulcanised"],"h":"An off-line step.","a":1,"id":361},{"d":"wk07-thermosets","p":19,"q":"Thermoset injection moulding is characterised by:","o":["High part cost and low tool cost","Low part cost, high tool cost and high production rate","Low production rate","Unstable materials"],"h":"High volume process.","a":1,"id":362},{"d":"wk07-thermosets","p":21,"q":"The advantage of foam moulding is the ability to:","o":["Increase section size and stiffness without significantly more material","Make transparent parts","Eliminate the mould","Produce thin film"],"h":"Also less shrinkage and better tolerances.","a":0,"id":363},{"d":"wk07-thermosets","p":22,"q":"The most common thermoset foams, used for furniture, bedding and auto seats, are:","o":["Polystyrene foams","Polyether or polyester polyurethanes","Phenolic foams","Silicone foams"],"h":"PU foam.","a":1,"id":364},{"d":"wk07-thermosets","p":23,"q":"Reaction injection moulding (RIM) is most commonly used with:","o":["Polyurethane foams, e.g. for large auto bezels, dashboards and fenders","PTFE","Glass","Bakelite"],"h":"Polymer reactants are mixed under high pressure.","a":0,"id":365},{"d":"wk07-thermosets","p":23,"q":"RIM cycle times are usually:","o":["Over 30 minutes","Less than two minutes","About 10 seconds","Several hours"],"h":"Fast for large parts.","a":1,"id":366},{"d":"wk07-thermosets","p":26,"q":"Transfer moulding is a modification of compression moulding in which:","o":["The resin is sprayed into the mould","The material is heated in an open cylinder and transferred under pressure into the cavity","No heat is used","The mould is rotated"],"h":"The material is transferred from a pot.","a":1,"id":367},{"d":"wk07-thermosets","p":28,"q":"Resin transfer moulding (RTM) process characteristics include:","o":["High production rate and high tooling cost","Low tooling cost, low production rate and high part strength","Low part strength","Parts that cannot be painted"],"h":"Good for low-volume strong parts.","a":1,"id":368},{"d":"wk07-thermosets","p":29,"q":"Polymer casting forms shapes by:","o":["Pouring liquid material into a mould without significant pressure, then curing","Injecting under high pressure","Forcing it through a die","Compressing powder"],"h":"Used for urethane and silicone elastomers.","a":0,"id":369},{"d":"wk07-thermosets","p":31,"q":"Rotational casting of thermosets differs from rotational moulding of thermoplastics because:","o":["It needs higher pressure","It is not necessary to heat the mould","It uses no mould","It rotates on only one axis"],"h":"Liquid reactants cure on their own.","a":1,"id":370},{"d":"wk07-thermosets","p":32,"q":"Sintering of high-temperature polymers such as fluorocarbons and polyimides involves:","o":["Melting and flowing the polymer","Compressing particles and heating until they join by coalescence without melting","Mixing resin and hardener","Vulcanising with sulfur"],"h":"The particles do not melt and flow.","a":1,"id":371},{"d":"wk07-thermosets","p":33,"q":"Vulcanisation of rubber is a chemical process in which:","o":["Polymer molecules are linked by atomic bridges, making rubber harder and more durable","Rubber is melted and recycled","Rubber is foamed","Plasticisers are added"],"h":"It is irreversible.","a":0,"id":372},{"d":"wk07-thermosets","p":35,"q":"The chemical crosslinking in vulcanisation is usually done with:","o":["Chlorine","Sulfur","Carbon dioxide","Nitrogen"],"h":"Popularised by Charles Goodyear.","a":1,"id":373},{"d":"wk07-thermosets","p":34,"q":"Uncured natural rubber perishes partly because:","o":["It crystallises","Proteins break down and large rubber molecules oxidise at their double bonds","It absorbs too much sulfur","It becomes too hard"],"h":"Sunlight accelerates it.","a":1,"id":374},{"d":"wk07-thermosets","p":33,"q":"Vulcanisation changes the surface of rubber from:","o":["Sticky to a smooth soft surface that does not adhere to metal or plastic","Smooth to sticky","Hard to liquid","Transparent to opaque only"],"h":"Before vulcanisation, rubber is sticky.","a":0,"id":375},{"d":"wk07-thermosets","p":39,"q":"When thermosets are overheated, they:","o":["Melt and flow","Char and are often still usable","Become transparent","Return to liquid resin"],"h":"They do not melt.","a":1,"id":376},{"d":"wk07-thermosets","p":40,"q":"Some thermoplastics have higher use temperatures than thermosets, but they have little strength above about:","o":["60°C","120°C","260°C","1000°C"],"h":"And they melt when overheated.","a":2,"id":377},{"d":"wk07-thermosets","p":44,"q":"Polymer composite matrices are mostly made from:","o":["Epoxy, unsaturated polyester, other thermosets and a few thermoplastics","Glass and graphite","Aluminium and steel","Paper and cotton"],"h":"The reinforcements are glass, graphite, aramid etc.","a":0,"id":378},{"d":"wk07-thermosets","p":46,"q":"Wood is a natural composite in which ______ fibres provide reinforcement.","o":["Glass","Lignin-free carbon","Cellulose","Keratin"],"h":"Plant fibres.","a":2,"id":379},{"d":"wk07-thermosets","p":51,"q":"About what percentage of the Airbus A350's primary structure is carbon-fibre-reinforced polymer?","o":["19%","35%","53%","80%"],"h":"The highest of major commercial airliners.","a":2,"id":380},{"d":"wk07-thermosets","p":52,"q":"Compared with discontinuous (chopped) reinforcements, continuous reinforcements:","o":["Distribute loads throughout the structure and are more effective for creep and long-term strength","Are only used in thermoplastics","Have lower strength","Only improve short-term properties"],"h":"They offer the most potential to compete with metals.","a":0,"id":381},{"d":"wk07-thermosets","p":52,"q":"Polymer composites are replacing metals on automobiles mainly because of:","o":["Higher cost and better conductivity","Lower weight and resistance to rust and road salt corrosion","Higher density","Better weldability"],"h":"Lower strength, less costly composites.","a":1,"id":382},{"d":"wk07-thermosets","p":53,"q":"Thermoplastic matrices were primarily reinforced with:","o":["Chopped glass fibres (a few mm) blended into moulding pellets","Continuous carbon fibre","Aramid weaves","Metal honeycomb"],"h":"Injection moulded glass-filled nylon.","a":0,"id":383},{"d":"wk07-thermosets","p":54,"q":"The most important thermosetting matrix resins are:","o":["PVC, PE and PP","Phenolics, epoxies and unsaturated polyesters","Nylon, acetal and PET","Silicones and rubbers"],"h":"Three thermoset families.","a":1,"id":384},{"d":"wk07-thermosets","p":55,"q":"A major application of phenolic composites is:","o":["Boat hulls","Circuit boards","Fuel tanks","Bicycle frames"],"h":"Good electrical insulation and high modulus.","a":1,"id":385},{"d":"wk07-thermosets","p":57,"q":"Formica decorative laminates for kitchen counters use which resin?","o":["Phenolic","Epoxy","Unsaturated polyester","Polyurethane"],"h":"Layers of paper compression laminated.","a":0,"id":386},{"d":"wk07-thermosets","p":58,"q":"Particle boards widely used in furniture use which resin?","o":["Epoxy","Urea formaldehyde","Polyester","PTFE"],"h":"Similar to phenolic.","a":1,"id":387},{"d":"wk07-thermosets","p":59,"q":"A unique characteristic of epoxies is:","o":["High shrinkage on curing","Minimal physical size change on polymerisation, with no solvents or condensation products emitted","They can be remelted","They require sulfur to cure"],"h":"The catalyst becomes part of the structure.","a":1,"id":388},{"d":"wk07-thermosets","p":60,"q":"Epoxy shrink rates can be as low as:","o":["0.01% of dimension","1%","5%","10%"],"h":"Low shrinkage tendency.","a":0,"id":389},{"d":"wk07-thermosets","p":60,"q":"Epoxy resins are probably the most important matrix for high-performance composites due to:","o":["Low cost","High strength, low viscosity for wetting and low shrinkage","High shrinkage","Ease of remelting"],"h":"Two-component systems.","a":1,"id":390},{"d":"wk07-thermosets","p":61,"q":"By far the most important resins for general-purpose composites, e.g. fibreglass boats and the Corvette, are:","o":["Epoxies","Unsaturated polyesters","Phenolics","Polyimides"],"h":"Much lower in cost than epoxies.","a":1,"id":391},{"d":"wk07-thermosets","p":61,"q":"Compared to epoxies, unsaturated polyesters are:","o":["Much lower in cost and slightly lower in strength","More expensive and stronger","Thermoplastics","Only used with carbon fibre"],"h":"General-purpose.","a":0,"id":392},{"d":"wk07-thermosets","p":62,"q":"The smooth, pigmented outer skin on fibreglass boats is called the:","o":["Mat","Gel coat","Roving","Prepreg"],"h":"Made from UP with fillers.","a":1,"id":393},{"d":"wk07-thermosets","p":62,"q":"Pipe and structural composite shapes are typically made by:","o":["Hand lay-up","Spray-up","Pultrusion","Vacuum bagging"],"h":"Fibre and resin are pulled through a die.","a":2,"id":394},{"d":"wk07-thermosets","p":65,"q":"The biggest advantages of paper and cotton reinforcements are:","o":["Low cost and ease of machining","Highest strength and stiffness","Lowest weight","Transparency"],"h":"Hard reinforcements cause tool wear.","a":0,"id":395},{"d":"wk07-thermosets","p":66,"q":"Beehive-pattern aluminium honeycomb panels are important in:","o":["Plumbing","The aircraft industry","Food packaging","Circuit boards"],"h":"Extremely light for a given section modulus.","a":1,"id":396},{"d":"wk07-thermosets","p":67,"q":"European car makers are developing metal/plastic/metal laminates for hoods because they:","o":["Are transparent","Can be stamped and deep drawn much like steel sheet","Cannot corrode at all","Need no tooling"],"h":"Easier and cheaper than honeycomb.","a":1,"id":397},{"d":"wk07-thermosets","p":68,"q":"Kevlar aramid fibre has a tensile strength of about:","o":["420 MPa","1000 MPa","3102 MPa","100 MPa"],"h":"Steel UTS is about 420 MPa.","a":2,"id":398},{"d":"wk07-thermosets","p":69,"q":"The main advantages of Kevlar over glass reinforcement are:","o":["Greater toughness and lighter weight","Lower cost and easier machining","Higher temperature resistance and conductivity","Transparency"],"h":"A 5 m canoe weighs only 7 kg.","a":0,"id":399},{"d":"wk07-thermosets","p":69,"q":"Nomex is a high-temperature nylon that, compared with Kevlar, is:","o":["Stronger","Not as strong, but easier to process and lower in cost","Heavier and more brittle","Electrically conductive"],"h":"Used for anti-flash gear.","a":1,"id":400},{"d":"wk07-thermosets","p":70,"q":"PAN carbon fibres can have a tensile modulus in excess of:","o":["210,000 MPa","758,000 MPa (100 million psi)","70,000 MPa","3,102 MPa"],"h":"Extremely high stiffness.","a":1,"id":401},{"d":"wk07-thermosets","p":71,"q":"Carbon fibres are used where:","o":["Glass reinforcement will not provide the desired stiffness or weight reduction","Low cost is the top priority","Electrical insulation is required","Transparency is needed"],"h":"They are grown smaller than 0.005 mm diameter.","a":0,"id":402},{"d":"wk07-thermosets","p":72,"q":"The most common reinforcement for polymer composites is:","o":["Carbon fibre","Kevlar","Glass fibre","Cotton"],"h":"Made by flowing molten glass through tiny holes.","a":2,"id":403},{"d":"wk07-thermosets","p":72,"q":"E glass is named for:","o":["Electrical applications, being a lower cost borosilicate glass","Extra strength","Epoxy compatibility","Elastic behaviour"],"h":"S glass has higher tensile strength.","a":0,"id":404},{"d":"wk07-thermosets","p":72,"q":"S glass, compared with E glass, is a magnesia/alumina/silica glass with:","o":["Lower cost","Higher tensile strength","Better electrical insulation only","Lower melting point"],"h":"S for strength.","a":1,"id":405},{"d":"wk07-thermosets","p":73,"q":"The use of two-dimensional weaves in laminates produces:","o":["Isotropic strength","Anisotropic strength, with one direction always weaker","Zero strength through the thickness only","Transparency"],"h":"3D weaves are an area of research.","a":1,"id":406},{"d":"wk07-thermosets","p":74,"q":"Glass fibre mats, compared with weaves:","o":["Require more resin for saturation but give a better surface texture","Require less resin and give a rougher surface","Are continuous fibres","Cannot be used with polyester"],"h":"Randomly intertwined discontinuous fibres.","a":0,"id":407},{"d":"wk07-thermosets","p":74,"q":"Bundles of glass strands formed into a large continuous strand are called:","o":["Mat","Roving","Chopped strand","Gel coat"],"h":"Heavy composites use cloths woven from it.","a":1,"id":408},{"d":"wk07-thermosets","p":77,"q":"In contact moulding (hand lay-up), the maximum composite thickness is usually about:","o":["1 mm","9 mm","50 mm","100 mm"],"h":"Layers of resin and glass are built up.","a":1,"id":409},{"d":"wk07-thermosets","p":78,"q":"Filament winding is widely used to make:","o":["Boat hulls and bathtubs","Pipes and tanks to handle chemicals","Circuit boards","Car dashboards"],"h":"Strands are wound around a mandrel.","a":1,"id":410},{"d":"wk07-thermosets","p":78,"q":"In filament winding, the winding pattern can be varied to:","o":["Control the strength characteristics of the composite","Change the colour","Remove the need for resin","Make the part transparent"],"h":"Extra layers in high-stress areas.","a":0,"id":411},{"d":"wk07-thermosets","p":79,"q":"Sheet moulding compound (SMC) consists of:","o":["Chopped fibres kneaded like dough with thickened resin","Catalysed resin kneaded into glass reinforcement by rollers into a sheet","Pure resin film","Woven aramid prepreg only"],"h":"Cut to size and pressed in a matched mould.","a":1,"id":412},{"d":"wk07-thermosets","p":80,"q":"Bulk moulding compound (BMC) resembles:","o":["A glob of dough of thickened resin and chopped fibres","A thin sheet","A continuous roving","A honeycomb"],"h":"Used for compression moulding charges.","a":0,"id":413},{"d":"wk07-thermosets","p":81,"q":"Continuous pultrusion makes glass-reinforced shapes by:","o":["Spraying chopped glass on a mould","Pulling resin-impregnated glass strands through a heated die","Pushing a billet through a die","Winding on a mandrel"],"h":"Pipes, channels and I-beams.","a":1,"id":414},{"d":"wk07-thermosets","p":82,"q":"Chopped fibre spraying is faster than hand lay-up, but:","o":["The chopped reinforcement is not as strong as mat or woven roving lay-ups","It cannot make large parts","It requires a matched metal mould","It only works with epoxy"],"h":"Used for shower stalls and bathtubs.","a":0,"id":415},{"d":"wk07-thermosets","p":83,"q":"Resin transfer moulding improves on contact moulding because it:","o":["Needs no mould","Produces two finished surfaces instead of one","Uses no resin","Is only for small parts"],"h":"A close-fitting mould is closed and resin is pumped in.","a":1,"id":416},{"d":"wk07-thermosets","p":84,"q":"Vacuum bag forming eliminates the high cost of matched metal moulds by using:","o":["Centrifugal force","Atmospheric pressure","Hydraulic rams","Explosives"],"h":"A vacuum is pulled under a bag.","a":1,"id":417},{"d":"wk07-thermosets","p":85,"q":"High-performance polymer composites are more likely to be made from:","o":["Thermoplastic resins","Thermosetting resins","Natural rubber","Recycled PET"],"h":"Epoxy and polyester matrices.","a":1,"id":418},{"d":"wk08-cutting","p":4,"q":"In manufacturing, cutting is divided into which four subgroups?","o":["Sheet, chip forming, nonchip forming and flame/thermal","Sawing, drilling, turning and milling","Punching, blanking, shearing and deburring","Laser, plasma, oxy-acetylene and EDM"],"h":"Fig: the cutting family tree.","a":0,"id":419},{"d":"wk08-cutting","p":6,"q":"In the sheet metal industry, rough-cutting or sizing sheet stock is normally referred to as:","o":["Cutting","Shearing","Machining","Broaching"],"h":"The scrap is called cut-offs or drops.","a":1,"id":420},{"d":"wk08-cutting","p":6,"q":"In the sheet metal industry, scrap from shearing is referred to as:","o":["Chips","Swarf","Cut-offs (or drops)","Burrs"],"h":"Leftover pieces of sheet.","a":2,"id":421},{"d":"wk08-cutting","p":7,"q":"Sheet-metal punching or shearing is limited to sheet thickness of:","o":["6 mm or less","1 mm or less","12 mm or less","25 mm or less"],"h":"The sheet/plate boundary.","a":0,"id":422},{"d":"wk08-cutting","p":9,"q":"Old dedicated punch-and-die technology is still needed for:","o":["One-off prototypes","Long runs, where a specially designed tool is most cost-effective","Cutting thick plate","Non-metals only"],"h":"High volume justifies the tool.","a":1,"id":423},{"d":"wk08-cutting","p":11,"q":"Punching and blanking are almost identical except:","o":["For which part is discarded: punching makes a hole, blanking keeps the cut-out shape","Blanking uses a laser","Punching is done hot","Blanking only applies to plastics"],"h":"The difference is what you keep.","a":0,"id":424},{"d":"wk08-cutting","p":13,"q":"A turret punch:","o":["Uses a single dedicated blanking die","Contains a turret with a variety of punches that can execute various sized holes nonstop","Uses a laser to cut holes","Is used for turning cylinders"],"h":"Rapid tool change.","a":1,"id":425},{"d":"wk08-cutting","p":15,"q":"CNC sheet metal punching centres have replaced the old method of designing a specific punch called a:","o":["Turret","Blanking die","Broach","Mandrel"],"h":"Standard punches make many hits instead.","a":1,"id":426},{"d":"wk08-cutting","p":17,"q":"The quality of a sheared edge depends mainly on the:","o":["Colour of the sheet","Clearance \"c\" between punch and die","Speed of the operator","Lubricant type"],"h":"Too large leads to distortion and big burrs.","a":1,"id":427},{"d":"wk08-cutting","p":18,"q":"Shearing is a tearing action that leaves a sharp residue called a(n):","o":["Chip","Burr","Kerf","Flash"],"h":"It must be removed by deburring.","a":1,"id":428},{"d":"wk08-cutting","p":19,"q":"Deburring and polishing of small metal parts is often done in a:","o":["Vibratory bowl with abrasive tumbling media","Lathe","Cupola","Vacuum bag"],"h":"Parts and media tumble together.","a":0,"id":429},{"d":"wk08-cutting","p":21,"q":"With computer controlled machining, which tolerance is now routine?","o":["1 mm","0.1 mm","0.01 mm","0.0001 mm"],"h":"In the recent past 0.1 mm was normal.","a":2,"id":430},{"d":"wk08-cutting","p":21,"q":"For high-precision machining work, tolerances of ______ or less can be achieved.","o":["0.002 mm","0.1 mm","0.05 mm","1 mm"],"h":"Very fine precision.","a":0,"id":431},{"d":"wk08-cutting","p":22,"q":"Chip-forming cutting is possible as long as:","o":["The workpiece is heated","The cutting tool is harder than the workpiece","The material is a thermoplastic","The workpiece is conductive"],"h":"The cutter must win.","a":1,"id":432},{"d":"wk08-cutting","p":22,"q":"When chip-forming cutting achieves tolerances of at least 0.1 mm, it is called:","o":["Shearing","Machining","Blanking","Sawing"],"h":"A special machine drives the tool.","a":1,"id":433},{"d":"wk08-cutting","p":25,"q":"Which of the following is NOT a reason machining is difficult to analyse?","o":["Very large strain and very high strain rate","Sensitivity to tool geometry, material and temperature","Prior work hardening greatly affects the process","The process is perfectly symmetrical and constrained"],"h":"It is bounded only by the cutting tool.","a":3,"id":434},{"d":"wk08-cutting","p":26,"q":"The two basic types of sawing are:","o":["Reciprocating and circular","Band and wire","Hot and cold","Rotary and radial"],"h":"Circular includes band and disc blades.","a":0,"id":435},{"d":"wk08-cutting","p":28,"q":"The most common cutting tool for drilling, usually made from high speed tool steel, is the:","o":["Reamer","Twist drill","Broach","End mill"],"h":"It cuts holes along one axis.","a":1,"id":436},{"d":"wk08-cutting","p":31,"q":"A reamer is used to:","o":["Create a hole from solid","Enlarge a previously formed hole by a small amount with high accuracy and smooth sides","Cut threads on a lathe","Grind flat surfaces"],"h":"A finishing step for holes.","a":1,"id":437},{"d":"wk08-cutting","p":32,"q":"In turning on a lathe:","o":["The workpiece held in a chuck rotates while the cutter is fed along it","The cutter rotates and the workpiece is fixed","The workpiece reciprocates under a tool","Abrasive grains remove chips"],"h":"Produces symmetrical cylindrical shapes.","a":0,"id":438},{"d":"wk08-cutting","p":32,"q":"A lathe is best suited to produce:","o":["Flat plates with pockets","Symmetrical cylindrical solid and hollow shapes, and threads","Large sheet metal enclosures","Deep drawn cups"],"h":"The workpiece spins.","a":1,"id":439},{"d":"wk08-cutting","p":39,"q":"Modern automated turning centres may be fitted with turret heads holding up to:","o":["2 tools","8 cutting tools each","100 tools each","1 tool"],"h":"Turret heads change tools quickly.","a":1,"id":440},{"d":"wk08-cutting","p":41,"q":"A vertical mill looks like a drill but differs because:","o":["It has much more flexibility in its axis of cutting and workpiece movement","It cannot cut metal","It only cuts vertically downward","It rotates the workpiece"],"h":"The head can be tilted.","a":0,"id":441},{"d":"wk08-cutting","p":43,"q":"Horizontal mills are no longer manufactured because they have been replaced by:","o":["Shapers","Machining centres","Lathes","Broaches"],"h":"CNC multi-axis machines.","a":1,"id":442},{"d":"wk08-cutting","p":47,"q":"A boring machine is used to:","o":["Make a hole from solid","Finish cut circular internal profiles in hollow workpieces or cast holes","Cut external threads","Flatten sheet"],"h":"Used to finish cannon barrels.","a":1,"id":443},{"d":"wk08-cutting","p":48,"q":"A shaper:","o":["Scrapes the surface with a reciprocating movement, mainly for finish cuts","Uses abrasive wheels","Is a high production process","Spins the workpiece"],"h":"Basically planing.","a":0,"id":444},{"d":"wk08-cutting","p":49,"q":"The shaping machine is particularly suited to machining flat surfaces where:","o":["Very small amounts of metal are removed very accurately","A large amount of metal has to be removed","Holes are required","Cylindrical parts are needed"],"h":"Milling is better for small, accurate removal.","a":1,"id":445},{"d":"wk08-cutting","p":50,"q":"The cutting tool in grinding is composed of:","o":["A single-point carbide insert","Hard abrasive grains (aluminium oxide, silicon carbide) bonded to a wheel","A traveling wire","A multi-toothed bar"],"h":"Each grain removes a small chip.","a":1,"id":446},{"d":"wk08-cutting","p":51,"q":"Grinding is a finishing operation, normally for bearing or sliding surfaces, with common tolerances of:","o":["±0.005 mm","±0.5 mm","±0.1 mm","±1 mm"],"h":"Very fine.","a":0,"id":447},{"d":"wk08-cutting","p":50,"q":"Which is NOT a basic grinding operation listed?","o":["Surface grinding","Cylindrical grinding","Centreless grinding","Reciprocating grinding"],"h":"The fourth is internal grinding.","a":3,"id":448},{"d":"wk08-cutting","p":53,"q":"A broach is:","o":["A long multi-toothed cutting tool, like a large file, used to finish internal and external surfaces in one pass","A rotary tool to enlarge holes slightly","A sheet metal punch","An abrasive wheel"],"h":"e.g. keyways.","a":0,"id":449},{"d":"wk08-cutting","p":54,"q":"The high cost of a special broach can be justified only for:","o":["One-off parts","High-quantity production","Plastic parts","Prototype runs"],"h":"Expensive tooling needs volume.","a":1,"id":450},{"d":"wk08-cutting","p":55,"q":"The machining centre is now the dominant machining process because:","o":["It is fast and accurate, cutting up to 5 sides without moving the part, at routine 0.01 mm tolerances","It is the cheapest machine","It uses no cutting tools","It only cuts plastics"],"h":"Reduces machining from days to hours.","a":0,"id":451},{"d":"wk08-cutting","p":57,"q":"A CNC turning centre program can exchange complete sets of tooling in less than:","o":["1 hour","10 minutes","30 seconds","1 second"],"h":"Formerly took one or more hours.","a":2,"id":452},{"d":"wk08-cutting","p":60,"q":"Nonchip forming cutting processes commonly achieve tolerances of:","o":["1 mm","0.5 mm","0.01 mm","0.0001 mm"],"h":"Used for electronic, scientific and defence equipment.","a":2,"id":453},{"d":"wk08-cutting","p":61,"q":"Thermal cutting processes are generally used for bulk cutting and achieve tolerances of about:","o":["0.001 mm","0.1 mm","1 mm","5 mm"],"h":"Not normally considered machining.","a":1,"id":454},{"d":"wk08-cutting","p":62,"q":"Chemical milling usually forms shallow cavities (up to about 12 mm) for:","o":["Decoration only","Overall weight reduction, e.g. aerospace parts","Threading","Polishing"],"h":"Hard-to-cut aerospace materials.","a":1,"id":455},{"d":"wk08-cutting","p":63,"q":"In chemical milling, selective attack on the workpiece is controlled by:","o":["A spark","Masks or partial immersion","An abrasive jet","A laser beam"],"h":"Low tooling cost, suited to low production.","a":1,"id":456},{"d":"wk08-cutting","p":64,"q":"Electro-chemical machining (ECM) is essentially the reverse of:","o":["Welding","Electroplating","Casting","Anodising only"],"h":"It removes metal instead of depositing it.","a":1,"id":457},{"d":"wk08-cutting","p":65,"q":"In ECM, tools are generally made of:","o":["Brass, copper, bronze or stainless steel","Carbon graphite only","Diamond","Aluminium oxide"],"h":"Conductive salt solution removes material.","a":0,"id":458},{"d":"wk08-cutting","p":65,"q":"ECM is suitable for:","o":["Very low production only","Medium to high production, despite expensive tooling and high power consumption","Plastics only","Wood"],"h":"Large amounts of metal from complex cavities.","a":1,"id":459},{"d":"wk08-cutting","p":66,"q":"In electrical discharge machining (EDM), metals are eroded by:","o":["Chemical etchants","Spark discharges through a nonconductive fluid","Abrasive particles","High pressure water"],"h":"The tool is typically carbon.","a":1,"id":460},{"d":"wk08-cutting","p":70,"q":"EDM is used extensively in producing:","o":["Injection and die-cast tooling","Bottles","Sheet metal enclosures","Timber furniture"],"h":"Errors are virtually eliminated.","a":0,"id":461},{"d":"wk08-cutting","p":70,"q":"Wire EDM uses ______ as a cutter.","o":["A rotating disc","A traveling wire","A laser beam","A water jet"],"h":"A recent development of EDM.","a":1,"id":462},{"d":"wk08-cutting","p":73,"q":"In abrasive-jet machining (AJM), grit is carried by:","o":["Clean dry air or gas at up to 300 m/s","Pure water at 1030 m/s","Oil","An electric arc"],"h":"The nozzle is tungsten carbide or sapphire.","a":0,"id":463},{"d":"wk08-cutting","p":74,"q":"AJM can cut very thin brittle materials without breakage because:","o":["It is very fast","There is little impact and little heat","It uses a vacuum","It melts the material"],"h":"It is slow and needs dust collection.","a":1,"id":464},{"d":"wk08-cutting","p":75,"q":"Water-jet cutting with abrasive (HDM) fires the stream at velocities up to:","o":["30 m/s","300 m/s","1030 m/s","10,000 m/s"],"h":"About 3400 fps.","a":2,"id":465},{"d":"wk08-cutting","p":76,"q":"Water-jet cutting is used to cut virtually any material:","o":["Without heat or particulate generation, with little waste and usually no finishing","Only metals under 1 mm","With a large heat-affected zone","Only plastics"],"h":"Clean, smooth cuts.","a":0,"id":466},{"d":"wk08-cutting","p":77,"q":"Water-jet cutting is low cost for production because:","o":["It uses cheap lasers","No tooling is required for setting up","It needs no water","It is slow"],"h":"No dies or punches.","a":1,"id":467},{"d":"wk08-cutting","p":80,"q":"Oxy-acetylene cutting can easily cut steel plates up to about:","o":["6 mm thick","25 mm thick","150 mm thick","1 m thick"],"h":"About 6 inches.","a":2,"id":468},{"d":"wk08-cutting","p":80,"q":"An advantage of oxy-acetylene cutting is:","o":["No gas tanks are needed","Portability, requiring no other power source (e.g. in shipyards)","It produces the narrowest kerf","It needs a high-voltage supply"],"h":"The tanks and hoses are a disadvantage.","a":1,"id":469},{"d":"wk08-cutting","p":81,"q":"In oxy-acetylene cutting, once the metal reaches critical temperature, increasing the oxygen flow:","o":["Oxidises the metal and creates the cut","Cools the metal","Hardens the edge","Welds the plate"],"h":"It is burning, not melting alone.","a":0,"id":470},{"d":"wk08-cutting","p":82,"q":"The most popular method of thermal cutting, with higher temperatures than oxy-acetylene and the ability to cut non-ferrous and stainless steel, is:","o":["Laser beam machining","Plasma-arc cutting","Electron beam machining","Abrasive jet machining"],"h":"It needs a high-voltage power source.","a":1,"id":471},{"d":"wk08-cutting","p":83,"q":"A real advantage of plasma-arc cutting over oxy-acetylene is that it:","o":["Needs no electricity","Is more compact and does not need cumbersome gas tanks and hoses","Cuts thicker steel","Is more portable for shipyards"],"h":"It requires a high-voltage power source instead.","a":1,"id":472},{"d":"wk08-cutting","p":87,"q":"Laser beam machining can drill holes as small as 0.005 mm with depth-to-diameter ratios of:","o":["1 to 1","5 to 1","50 to 1","500 to 1"],"h":"Used for the MacBook camera indicator holes.","a":2,"id":473},{"d":"wk08-cutting","p":86,"q":"In laser beam machining, the workpiece is:","o":["Melted and vaporised by highly focused, high-density energy","Eroded by sparks","Dissolved chemically","Abraded by grit"],"h":"It does not require a vacuum.","a":0,"id":474},{"d":"wk08-cutting","p":89,"q":"Electron beam machining (EBM) differs from LBM mainly because it:","o":["Needs no power","Requires a vacuum and produces hazardous x-rays","Is cheaper","Cannot cut metals"],"h":"Electrons are accelerated to 80% of light speed.","a":1,"id":475},{"d":"wk08-cutting","p":90,"q":"Compared with other thermal cutting processes, laser and electron beam cutting have:","o":["Better surface finish and narrower kerf width","Rougher finish and wider kerf","Lower accuracy","No heat input"],"h":"Extremely accurate cutting.","a":0,"id":476},{"d":"wk08-cutting","p":87,"q":"The tiny green camera light that shines through the MacBook's aluminium casing is made possible by holes produced by:","o":["Chemical milling","Water-jet cutting","Laser beam machining","Turret punching"],"h":"Micro-holes invisible to the eye.","a":2,"id":477},{"d":"wk09-joining","p":5,"q":"The three broad joining options available are:","o":["Thermo joining, adhesives and mechanical","Welding, soldering and brazing","Rivets, bolts and screws","Hot, warm and cold joining"],"h":"Fig: Joining family.","a":0,"id":478},{"d":"wk09-joining","p":6,"q":"Which is NOT listed as a consideration for choosing a joining process?","o":["Joint strength/reliability","Appearance","Repair/maintenance requirements","The colour of the operator's workwear"],"h":"Others include cost, quantity and facilities.","a":3,"id":479},{"d":"wk09-joining","p":7,"q":"The best strategy for joining is to:","o":["Minimise the need to assemble through creative design and design for assembly (DFA)","Always weld every part","Use as many fasteners as possible","Avoid automation"],"h":"Assembly is a large share of production time.","a":0,"id":480},{"d":"wk09-joining","p":7,"q":"It is quite common for assembly or mechanical fastening to take more than ____ of total production time.","o":["5%","20%","50%","90%"],"h":"Assembly is time consuming.","a":2,"id":481},{"d":"wk09-joining","p":9,"q":"Mechanical fasteners usually represent less than ____ of the total in-place cost of a product, though assembly often accounts for the major manufacturing cost.","o":["5%","25%","50%","75%"],"h":"Fasteners are cheap; labour is not.","a":0,"id":482},{"d":"wk09-joining","p":9,"q":"When using mechanical fasteners, the cost of assembling a product is typically proportional to:","o":["The weight of the product","The number of parts in the product","The colour of the product","The material density"],"h":"Fewer parts, lower assembly cost.","a":1,"id":483},{"d":"wk09-joining","p":14,"q":"In soldering and brazing:","o":["Two metallurgically similar metals are joined by a third metal with no fusion of the base metals","The base metals are fused together","No filler metal is used","Only plastics are joined"],"h":"The filler acts like a glue.","a":0,"id":484},{"d":"wk09-joining","p":15,"q":"Welding differs from soldering/brazing because:","o":["It uses lower temperatures","There is fusion of the metals being joined, often with mechanical or physical change","It cannot join metals","It needs no heat"],"h":"Heat treatment may be needed for a strong weld.","a":1,"id":485},{"d":"wk09-joining","p":16,"q":"Which is an advantage of soldering and brazing?","o":["Dissimilar metals and different thicknesses can be joined, with original properties not seriously affected","The joint is always stronger than the base metal","No flux is ever needed","They fuse the base metals"],"h":"Cast and wrought metals can be joined too.","a":0,"id":486},{"d":"wk09-joining","p":17,"q":"Soldering is done at temperatures below:","o":["150°C","455°C (850°F)","900°C","1230°C"],"h":"Brazing is above this temperature.","a":1,"id":487},{"d":"wk09-joining","p":17,"q":"Soldering is used primarily to:","o":["Join structural steel beams","Conduct electric current and seal cans","Join thick plates","Join plastics"],"h":"Electronics and sealing.","a":1,"id":488},{"d":"wk09-joining","p":18,"q":"Flux is used in soldering to:","o":["Prevent oxidation and allow the solder to bond as it cools","Increase the melting point","Act as filler metal","Cool the joint quickly"],"h":"Clean surfaces bond.","a":0,"id":489},{"d":"wk09-joining","p":26,"q":"Because solder has little strength, soldered joints should be:","o":["Placed under high stress","Designed to support the load, and used where the joint is not under stress","Made only with glass","Always butt joints"],"h":"Mechanical interlock helps.","a":1,"id":490},{"d":"wk09-joining","p":26,"q":"Limited nonmetals such as glass can be soldered when:","o":["Heated above 1000°C","Pre-coated to accept the solder","Sandblasted","Painted"],"h":"The surface must be metallised.","a":1,"id":491},{"d":"wk09-joining","p":27,"q":"The common solder alloy used for electronics is:","o":["Tin-lead","Zinc-aluminium","Cadmium-zinc","Copper-phosphorus"],"h":"The classic electronics solder.","a":0,"id":492},{"d":"wk09-joining","p":28,"q":"Brazing is done at temperatures:","o":["Below 455°C","Above 455°C but below the melting point of the parts being joined","Above the melting point of the base metals","At room temperature"],"h":"Hotter than soldering.","a":1,"id":493},{"d":"wk09-joining","p":29,"q":"Brazing is stronger than soldering because:","o":["Some limited alloying and intergranular penetration occurs between filler and base metals","The base metals melt","It uses no flux","It is done at lower temperature"],"h":"Atomic forces at the joint.","a":0,"id":494},{"d":"wk09-joining","p":31,"q":"Which is an advantage of brazing?","o":["Requires extensive finishing","Complex assemblies can be joined in several steps using filler metals with progressively lower melting temperatures","Produces high residual stress","The joint is not conductive"],"h":"Also stress-free and sealed joints.","a":1,"id":495},{"d":"wk09-joining","p":32,"q":"The filler metal used for brazing copper and its alloys is:","o":["Aluminium-silicon","Copper-phosphorus","Gold","Nickel-silver"],"h":"Brazed at 700-925°C.","a":1,"id":496},{"d":"wk09-joining","p":32,"q":"Aluminium alloys are typically brazed with which filler?","o":["Aluminium-silicon","Silver/copper","Gold","Magnesium-aluminium"],"h":"At 570-620°C.","a":0,"id":497},{"d":"wk09-joining","p":33,"q":"After brazing, flux residue must be removed because it is corrosive. The most common way is to:","o":["Sandblast it","Water quench the assembly in a hot water bath","Leave it to evaporate","Paint over it"],"h":"Fluxes are sodium, potassium and lithium compounds.","a":1,"id":498},{"d":"wk09-joining","p":34,"q":"Torch brazing is common for:","o":["Most limited production, being manual and versatile","Very high volume automated lines only","Large structures only","Joining plastics"],"h":"Uses a slightly reducing flame.","a":0,"id":499},{"d":"wk09-joining","p":37,"q":"Dip brazing of aluminium assemblies uses which heat source?","o":["An electrical coil","A molten salt bath","A hydrogen furnace","A laser"],"h":"The jigged assembly is dipped.","a":1,"id":500},{"d":"wk09-joining","p":38,"q":"In induction brazing, the heat source is:","o":["A gas torch","An electrical coil placed near the joint","A salt bath","Friction"],"h":"Normally automated, fast and uniform.","a":1,"id":501},{"d":"wk09-joining","p":39,"q":"No flux is necessary in furnace brazing because:","o":["The hydrogen-atmosphere furnace contains no oxygen","The temperature is too low to oxidise","The parts are pre-painted","A salt bath is used"],"h":"Flux prevents oxidation, which needs oxygen.","a":0,"id":502},{"d":"wk09-joining","p":40,"q":"In oxyacetylene gas welding, the metal pieces are heated:","o":["Below their melting temperature","Above their melting temperature so they flow together","By an electric arc","By friction"],"h":"Fusion welding.","a":1,"id":503},{"d":"wk09-joining","p":43,"q":"In gas welding, pieces to be welded must be of similar:","o":["Thickness, melting temperature and metallurgy","Colour and texture","Length only","Hardness only"],"h":"Unlike brazing.","a":0,"id":504},{"d":"wk09-joining","p":44,"q":"The stress caused as a gas-welded joint cools can be relieved by:","o":["Painting","Heat treatment","Quenching","Shot peening only"],"h":"Grain structure changes during welding.","a":1,"id":505},{"d":"wk09-joining","p":46,"q":"The most common method of arc welding, also called stick welding, is:","o":["MIG (GMAW)","TIG (GTAW)","Shielded-metal arc welding (SMAW)","Plasma arc welding"],"h":"Uses a flux-covered electrode.","a":2,"id":506},{"d":"wk09-joining","p":47,"q":"In SMAW, the flux covering of the electrode:","o":["Protects the molten metal from oxidising","Acts as the tungsten arc tip","Cools the weld","Is not consumed"],"h":"It forms slag.","a":0,"id":507},{"d":"wk09-joining","p":48,"q":"In stick welding, before another pass is made, the slag must be:","o":["Melted again","Removed by chipping","Painted","Left to protect the weld"],"h":"The melted flux collects on the weld.","a":1,"id":508},{"d":"wk09-joining","p":49,"q":"SMAW cannot be automated because of:","o":["The required gas tanks","The limited length of the electrode","High equipment cost","Its high precision"],"h":"The stick must be replaced as it is consumed.","a":1,"id":509},{"d":"wk09-joining","p":52,"q":"Gas metal arc welding (GMAW) is also called:","o":["TIG welding","MIG (metal inert gas) welding","Stick welding","Stud welding"],"h":"Uses a bare wire electrode fed from a reel.","a":1,"id":510},{"d":"wk09-joining","p":53,"q":"The real advantage of MIG welding over stick welding is:","o":["No melted flux or slag to remove, giving an uncontaminated weld","Lower cost","Greater maneuverability","No gas is needed"],"h":"An inert gas shield replaces flux.","a":0,"id":511},{"d":"wk09-joining","p":53,"q":"Compared with stick welding, MIG welding:","o":["Is cheaper and more maneuverable","Costs more and is less maneuverable because of the required gas tanks","Cannot be automated","Uses a tungsten electrode"],"h":"Trade-off for a cleaner weld.","a":1,"id":512},{"d":"wk09-joining","p":55,"q":"In stud arc welding:","o":["A stud acting as the electrode is fused onto a metal surface with a stud-welding gun","Two cylinders are rotated against each other","Sheets are clamped between two electrodes","A laser fuses the stud"],"h":"Pull the trigger, melt, press, withdraw.","a":0,"id":513},{"d":"wk09-joining","p":58,"q":"Gas-tungsten arc welding (GTAW) is also called:","o":["MIG welding","TIG (tungsten inert gas) welding","Stick welding","Flash welding"],"h":"The electrode is tungsten.","a":1,"id":514},{"d":"wk09-joining","p":59,"q":"In TIG welding, the tungsten electrode:","o":["Is consumed as filler","Does not melt and is not consumed; a separate filler rod is used if needed","Is coated with flux","Is a reel of wire"],"h":"Tungsten has a very high melting point.","a":1,"id":515},{"d":"wk09-joining","p":60,"q":"TIG welding is especially suited to:","o":["High-quality welding of thin materials and nearly all metals including aluminium and titanium","Very thick steel only","Plastics only","Low-quality fast welding"],"h":"A precision process.","a":0,"id":516},{"d":"wk09-joining","p":61,"q":"Plasma arc welding achieves greater energy concentration because:","o":["It uses a flux-coated electrode","The arc is constricted by being forced through a small orifice","It operates in a vacuum","It uses lower current"],"h":"Not diffused as in other processes.","a":1,"id":517},{"d":"wk09-joining","p":62,"q":"Plasma arc welding temperatures can reach about:","o":["1,500°C","5,000°C","33,315°C (60,000°F)","300°C"],"h":"Extremely hot.","a":2,"id":518},{"d":"wk09-joining","p":64,"q":"A disadvantage of plasma arc welding is:","o":["Longer welding time","More complex process requiring two protective gases","More joint preparation","Less tolerance for joint mismatch"],"h":"Shielding is difficult.","a":1,"id":519},{"d":"wk09-joining","p":65,"q":"Resistance spot welding is widely used in:","o":["Sheet-metal fabrication and the automotive industry","Joining thick castings","Plastic bottles","Glass products"],"h":"Simple, rapid and economical.","a":0,"id":520},{"d":"wk09-joining","p":66,"q":"Spot welding leaves small depressions at contact points; these can be reduced on the finish side by:","o":["Adding filler metal","Adjusting the electrode pressure","Using flux","Increasing the current only"],"h":"The electrodes squeeze the sheets.","a":1,"id":521},{"d":"wk09-joining","p":69,"q":"In resistance projection welding (RPW), heat is localised by:","o":["Embossed dimples or projections raised on the sheet","A tungsten electrode","A rotating spindle","A molten salt bath"],"h":"They collapse under heat and pressure.","a":0,"id":522},{"d":"wk09-joining","p":70,"q":"High-frequency (450 kHz) welding is used to produce:","o":["Spot welds on car bodies","Long continuous seam welds on steel tubes","Stud welds","Ultrasonic welds on foil"],"h":"Rollers squeeze the tube sides together.","a":1,"id":523},{"d":"wk09-joining","p":73,"q":"Flash welding is commonly used in model shops to:","o":["Weld plastics","Repair broken band saw blades by end joining","Spot weld sheet","Join glass"],"h":"Ends are clamped and a 2000-5000 A current is applied.","a":1,"id":524},{"d":"wk09-joining","p":75,"q":"Ultrasonic bonding converts a high frequency of 10-75 kHz into:","o":["Heat from an arc","Mechanical vibrations transmitted to the workpiece","Light energy","Chemical reactions"],"h":"Also commonly used to join plastics.","a":1,"id":525},{"d":"wk09-joining","p":75,"q":"Ultrasonic bonding is used for:","o":["Lap welding thin sheet and wire, sealing foil packaging and joining plastics","Welding thick steel plates","Brazing copper pipes","Joining cast iron"],"h":"Vibrations create the bond.","a":0,"id":526},{"d":"wk09-joining","p":78,"q":"Friction bonding is a solid state welding process used to join:","o":["Thin sheets","Cylindrical parts, by rotating one rapidly against the other","Foil packaging","Glass to metal"],"h":"Heat comes from rubbing.","a":1,"id":527},{"d":"wk09-joining","p":81,"q":"An advantage of laser beam welding over electron beam welding is that LBW:","o":["Requires no vacuum and generates no x-rays","Needs a vacuum","Produces more spatter","Has lower weld quality"],"h":"Better weld quality too.","a":0,"id":528},{"d":"wk09-joining","p":81,"q":"The Gillette Mach3 razor's three narrow blades are joined by 33 pinpoint welds made by:","o":["Resistance spot welding","Ultrasonic welding","Nd:YAG laser beam welding","Stud welding"],"h":"0.5 mm diameter welds.","a":2,"id":529},{"d":"wk09-joining","p":8,"q":"Brazing, welding and adhesives are not economical to automate unless:","o":["The parts are plastic","There is sufficient production quantity","The parts are very large","No tolerances are required"],"h":"Shipbuilding and oil rigs stay manual.","a":1,"id":530},{"d":"wk10-joining","p":56,"q":"The common technique used for joining acrylic parts using chloroform is a kind of ______ method.","o":["cyanoacrylate bonding","anaerobic bonding","epoxy bonding","solvent bonding"],"h":"The liquid dissolves the surfaces so they flow together.","a":3,"id":531},{"d":"wk10-joining","p":56,"q":"Solvent bonding is a common technique for joining parts moulded from:","o":["Amorphous thermoplastic resins","Thermosets","Crystalline metals","Ceramics"],"h":"The solvent dissolves the mating surfaces.","a":0,"id":532},{"d":"wk10-joining","p":56,"q":"After solvent bonding and evaporation of the solvent, what remains is:","o":["A layer of epoxy","A pure material-to-material bond","A mechanical interlock","A layer of flux"],"h":"No foreign adhesive is left.","a":1,"id":533},{"d":"wk10-joining","p":56,"q":"Which is listed as an effective solvent for bonding ABS?","o":["Water","Acetone, methylene chloride or MEK","Sulfur","Ethanol only"],"h":"Common lab solvents.","a":1,"id":534},{"d":"wk10-joining","p":4,"q":"Which of the following is NOT a thermoplastic fusion joining method?","o":["Ultrasonic welding","Spin welding","Hot plate welding","Riveting"],"h":"Riveting is a mechanical method.","a":3,"id":535},{"d":"wk10-joining","p":5,"q":"Ultrasonic welding of thermoplastics provides strong, reliable bonds at very fast cycle times, but:","o":["Each application requires a customised horn and fixturing, adding expense","It cannot join thermoplastics","It requires flux","It is very slow"],"h":"The horn transmits vibration.","a":0,"id":536},{"d":"wk10-joining","p":8,"q":"Which factor most influences successful ultrasonic welding?","o":["Colour of the resin","Uniform wall sections and simplicity of shape","Use of flux","Long cooling time in water"],"h":"Also resin grade, cleanliness, weld time and clamping pressure.","a":1,"id":537},{"d":"wk10-joining","p":9,"q":"Vibration welding works by:","o":["Rubbing two similar plastic parts together under pressure until frictional heat melts the interface","Rotating one part at high speed against another","Using a heated platen","Exposing a ferromagnetic gasket to a magnetic field"],"h":"Linear reciprocating friction.","a":0,"id":538},{"d":"wk10-joining","p":10,"q":"In vibration welding, mating part surfaces must be:","o":["Curved and irregular","Parallel, since complex or irregular surfaces usually cannot be welded","Coated with flux","Metallised"],"h":"The basic joint is a butt profile.","a":1,"id":539},{"d":"wk10-joining","p":11,"q":"An advantage of vibration welding is that the reciprocating motion:","o":["Pushes surface contaminants such as mould release and paint out of the weld area","Allows welding in multiple planes","Requires the cheapest equipment","Needs no pressure"],"h":"It is self-cleaning at the interface.","a":0,"id":540},{"d":"wk10-joining","p":11,"q":"A disadvantage of vibration welding is:","o":["It cannot make hermetic seals","The weld is generally limited to a single plane","It cannot weld internal walls","It only handles tiny parts"],"h":"Equipment cost is also higher.","a":1,"id":541},{"d":"wk10-joining","p":12,"q":"Spin welding joins thermoplastic parts by:","o":["Vibrating them linearly","Rotating one part at high speed against a fixed part under pressure","Heating with a platen","Using a solvent"],"h":"Best for round parts.","a":1,"id":542},{"d":"wk10-joining","p":13,"q":"Which spin weld joint design tends to provide weaker bonds?","o":["Tongue and groove","Scarf joint","Shear joint","Butt joint"],"h":"The others give more bond area.","a":3,"id":543},{"d":"wk10-joining","p":14,"q":"Electromagnetic welding uses a gasket containing:","o":["Minute ferromagnetic particles in a matrix of the same thermoplastic","Glass fibres","Solder","Tungsten wire"],"h":"The particles heat up in an oscillating magnetic field.","a":0,"id":544},{"d":"wk10-joining","p":15,"q":"The electromagnetic welding process typically takes:","o":["Less than 0.1 seconds","3 to 10 seconds","15 to 20 minutes","Several hours"],"h":"Depends on weld area and resin.","a":1,"id":545},{"d":"wk10-joining","p":17,"q":"In hot plate welding:","o":["Parts are heated against a heated insert, which is removed before pressing the parts together","One part is spun against another","A solvent is applied","Parts are vibrated"],"h":"Cycle usually 15-20 seconds.","a":0,"id":546},{"d":"wk10-joining","p":18,"q":"Hot plate welding usually uses which joint type due to the flat platens?","o":["Tongue and groove","Butt joints and variations","Lap joints only","Scarf joints only"],"h":"Joint design is mainly for cosmetic bead hiding.","a":1,"id":547},{"d":"wk10-joining","p":19,"q":"Staking is:","o":["Welding two flat sheets with a vibrating horn","Deforming a plastic stud or boss to capture another part","Inserting a metal thread into plastic","Gluing with cyanoacrylate"],"h":"Done with heat or ultrasonic energy.","a":1,"id":548},{"d":"wk10-joining","p":19,"q":"Ultrasonic staking is often chosen over heat staking because:","o":["The tool tip stays relatively cool, forming a clean head with minimal sticking and stringing","It is cheaper in every case","It uses no energy","It works on metals"],"h":"Heat staking can string.","a":0,"id":549},{"d":"wk10-joining","p":21,"q":"Which is NOT a thermoplastic mechanical assembly option?","o":["Press-fits","Snap fits","Moulded-in threads","Spin welding"],"h":"Spin welding is thermal fusion.","a":3,"id":550},{"d":"wk10-joining","p":22,"q":"With press-fits, there is no physical bond at the interface, so:","o":["They are always hermetic","A hermetic seal should not be expected","They cannot join dissimilar materials","Temperature has no effect"],"h":"Strength comes from mechanical interference.","a":1,"id":551},{"d":"wk10-joining","p":22,"q":"Press-fit joint strength can change with temperature because of:","o":["Dissimilar coefficients of thermal expansion and changing creep rate","Solvent evaporation","Flux corrosion","Electrical conductivity"],"h":"Plastics and metals expand differently.","a":0,"id":552},{"d":"wk10-joining","p":24,"q":"Threaded inserts should be considered for plastic parts when:","o":["The part will never be disassembled","Repeated assembly/disassembly is required or engagement length is insufficient","The part is transparent","Solvent bonding is used"],"h":"Plastic threads wear out.","a":1,"id":553},{"d":"wk10-joining","p":26,"q":"Which insert installation methods are the fastest and easiest, but also the weakest?","o":["Press fit and expansion insertion","Ultrasonic and thermal insertion","Moulded-in insertion","Self-tapping insertion"],"h":"Little or no melting involved.","a":0,"id":554},{"d":"wk10-joining","p":28,"q":"In ultrasonic insertion of inserts:","o":["The insert is moulded in","High frequency vibration causes frictional melting at the insert/plastic interface, which solidifies around the insert","The insert is glued","The screw expands the insert flanges"],"h":"The horn contacts the insert.","a":1,"id":555},{"d":"wk10-joining","p":30,"q":"A less expensive alternative to ultrasonic insertion is:","o":["Moulded-in insertion","Thermal insertion","Expansion insertion","Electromagnetic welding"],"h":"A heat source melts a thin layer.","a":1,"id":556},{"d":"wk10-joining","p":32,"q":"A major disadvantage of moulded-in inserts is:","o":["High moulded-in stresses due to differences in thermal expansion between metal and plastic","They are the weakest method","No cycle time increase","They cannot be used with injection moulding"],"h":"Thicker bosses are needed around them.","a":0,"id":557},{"d":"wk10-joining","p":33,"q":"Snap fits eliminate fasteners by using:","o":["Adhesives","The inherent flexibility of plastics and the moulded-in capability of injection moulding","Heat to melt the parts","Solvents"],"h":"They can be one-time or multiple use.","a":1,"id":558},{"d":"wk10-joining","p":38,"q":"Mechanical fasteners are an excellent assembly option for plastics when:","o":["Surface appearance is not important or disassembly may be required","A hermetic seal is required","The part is very thin","Invisible joints are needed"],"h":"Strong, inexpensive and quick.","a":0,"id":559},{"d":"wk10-joining","p":39,"q":"The two classifications of self-tapping screws are:","o":["Machine and lag screws","Thread forming (TF) and thread cutting (TC)","Pan head and truss head","Blind and solid"],"h":"Forming vs cutting the thread.","a":1,"id":560},{"d":"wk10-joining","p":40,"q":"Thread cutting screws are not used for repeated assembly because:","o":["They are too weak","Reinsertion may form a second set of threads","They induce high residual stress","They are too expensive"],"h":"Care is needed to find the original thread.","a":1,"id":561},{"d":"wk10-joining","p":40,"q":"Thread forming screws can induce high residual stresses, which is acceptable in:","o":["Softer, more ductile plastics where stress relaxation occurs","Brittle plastics","Glass","All plastics without exception"],"h":"The stresses eventually subside.","a":0,"id":562},{"d":"wk10-joining","p":41,"q":"In clamped fastener designs in plastics, stress relaxation over time may cause screws to back off. This can be helped by:","o":["Using thread cutting screws","Locking fasteners and washers to distribute load","Heating the joint","Removing the boss"],"h":"Spread the load.","a":1,"id":563},{"d":"wk10-joining","p":43,"q":"When riveting plastics, aluminium rivets are preferred over steel because:","o":["Aluminium more readily deforms under high stress","They are stronger","They conduct heat","They are cheaper than plastics"],"h":"Reduces stress on the plastic.","a":0,"id":564},{"d":"wk10-joining","p":43,"q":"To reduce stress concentrations when riveting plastic parts, it is suggested to use:","o":["Small heads and sharp corners","Large diameter heads, reinforcing washers and radiused corners","Steel rivets only","No holes"],"h":"Distribute stresses.","a":1,"id":565},{"d":"wk10-joining","p":47,"q":"Synthetic organic adhesives are often used for:","o":["Load bearing applications, joining thin materials and invisible joints","Joints in peel only","High-temperature furnace parts only","Electrical conduction only"],"h":"Strength, toughness and environmental resistance are needed.","a":0,"id":566},{"d":"wk10-joining","p":48,"q":"An adhesive joint should be designed to withstand shear, compressive and tensile forces, but should NOT be subjected to:","o":["Shear","Compression","Peeling","Tension"],"h":"Labels come off by peeling.","a":2,"id":567},{"d":"wk10-joining","p":50,"q":"Which is an advantage of adhesives?","o":["They distribute stress uniformly and can join dissimilar materials","They have unlimited shelf life","They allow non-destructive testing","They need no surface preparation"],"h":"Also seal and dampen.","a":0,"id":568},{"d":"wk10-joining","p":51,"q":"Which is a disadvantage of adhesives?","o":["They deface exposed surfaces","They cannot join thin parts","Limited shelf life and destructive testing only","They concentrate stress"],"h":"Also need thorough cleaning.","a":2,"id":569},{"d":"wk10-joining","p":57,"q":"Adhesive bonding is convenient for joining plastic to similar or dissimilar materials, and can provide:","o":["Only temporary bonds","A hermetic seal if needed, with stress distributed over the bond area","Electrical conduction always","Disassembly without damage"],"h":"Loctite and ThreeBond are suppliers.","a":1,"id":570},{"d":"wk10-joining","p":58,"q":"Typical screening of an adhesive with a particular substrate consists of:","o":["A compatibility evaluation and a strength/adhesion test","An x-ray test and a colour test","A hardness and creep test","Only a peel test"],"h":"Two tests.","a":0,"id":571},{"d":"wk10-joining","p":59,"q":"Two-part epoxies consist of:","o":["A primer and a catalyst","A resin and a hardener mixed in strict proportions","A solvent and a resin","Moisture and a monomer"],"h":"One-part epoxies need heat curing instead.","a":1,"id":572},{"d":"wk10-joining","p":59,"q":"One-part epoxies require curing by heat, usually around:","o":["Room temperature for 10 seconds","148°C (300°F) for one hour or more","1000°C for 1 minute","UV light for 3 seconds"],"h":"No mixing but heat is needed.","a":1,"id":573},{"d":"wk10-joining","p":59,"q":"Unlike many other adhesives, epoxies:","o":["Are not solvent based but cure by chemical reaction","Cure by absence of oxygen","Cure from surface moisture","Cure only in UV light"],"h":"A chemical crosslinking reaction.","a":0,"id":574},{"d":"wk10-joining","p":60,"q":"Urethane adhesives are primarily used in applications requiring:","o":["Very fast setting in seconds","High strength as well as flexibility","Curing in the absence of oxygen","No mixing at all ever"],"h":"Polyurethanes.","a":1,"id":575},{"d":"wk10-joining","p":60,"q":"Anaerobic adhesives cure when triggered by:","o":["The presence of surface moisture","The absence of oxygen","UV light only","Mixing with a hardener"],"h":"Used for threadlockers.","a":1,"id":576},{"d":"wk10-joining","p":61,"q":"Cyanoacrylate (super glue) curing is initiated by:","o":["The presence of surface moisture, even humidity in the air","The absence of oxygen","Heat above 148°C","Mixing two parts"],"h":"Sets in 2-3 seconds.","a":0,"id":577},{"d":"wk10-joining","p":61,"q":"Cyanoacrylates have a normal setting time of ____ and full cure in ____.","o":["60-90 s; 30 min","2-3 seconds; 24 hours","15 s; 2-24 hours","5 min; 1 hour"],"h":"Convenience adhesives.","a":1,"id":578},{"d":"wk10-joining","p":61,"q":"UV curable adhesives use light energy to initiate polymerisation, typically curing in:","o":["3 to 10 seconds","24 hours","1 hour at 148°C","30 minutes"],"h":"Extremely fast.","a":0,"id":579},{"d":"wk10-joining","p":62,"q":"\"Improved\" acrylic adhesives offer the advantage of:","o":["Curing without any catalyst ever","Rarely needing primers, with setting in about 60-90 seconds","Being solvent bonds","Only bonding metals"],"h":"Full cure within 30 minutes.","a":1,"id":580},{"d":"wk10-joining","p":64,"q":"In flame treatment as a surface preparation for adhesives, the surface is exposed to:","o":["The yellow zone of the flame","The oxidising (blue) area of a flame","A UV lamp","An acid bath"],"h":"Oxidises the surface.","a":1,"id":581},{"d":"wk10-joining","p":64,"q":"Corona discharge surface treatment involves:","o":["Placing the material between two electrodes so electron and ion bombardment oxidises the surface","Dipping in acid","Sanding with abrasives","A vacuum chamber filled with inert gas"],"h":"Electrical surface activation.","a":0,"id":582},{"d":"wk10-joining","p":64,"q":"Which surface preparation places the substrate in a vacuum chamber filled with inert gas under high electrical tension?","o":["Corona discharge","Plasma treatment","Chemical etch","Flame treatment"],"h":"Similar surface oxidation results.","a":1,"id":583},{"d":"wk10-joining","p":66,"q":"Standardisation of fasteners is recommended because:","o":["The real cost is in accommodating and supplying various-sized fasteners in assembly","Different sizes are always cheaper","It increases part count","It allows more colours"],"h":"Saving a few cents per screw is false economy.","a":0,"id":584},{"d":"wk10-joining","p":68,"q":"The most common fasteners used in assembly are:","o":["Rivets","Threaded fasteners","Staples","Snap fits"],"h":"Drill and tap for a machine screw.","a":1,"id":585},{"d":"wk10-joining","p":70,"q":"Fasteners for insertion into sheet metal are commonly called \"pems\", after:","o":["A type of rivet","Penn Engineering and Manufacturing Company","Pneumatic Electrical Machines","Plastic Embedded Metal"],"h":"One of the first developers.","a":1,"id":586},{"d":"wk10-joining","p":75,"q":"A rivet makes a joint by:","o":["Clamping the two parts between heads, the second head formed by upsetting","Melting the base metals","Gluing the parts","Threading into a tapped hole"],"h":"Solid or hollow.","a":0,"id":587},{"d":"wk10-joining","p":76,"q":"Blind (pop) rivets are:","o":["Solid rivets formed by hot upsetting","Tubular rivets inserted from one side, expanded by pulling a mandrel which then breaks off","Rivets that are invisible after painting","Threaded inserts"],"h":"Only one side needs access.","a":1,"id":588},{"d":"wk10-joining","p":77,"q":"Because a rivet hole is a discontinuity that could cause fatigue failure, in critical applications the hole is:","o":["Left rough","Deburred, reamed or slightly expanded to induce residual compressive stress","Welded shut","Made larger than the rivet"],"h":"Remove stress raisers.","a":1,"id":589},{"d":"wk10-joining","p":77,"q":"Riveting remains of great importance in:","o":["Building construction","Automotive frames","Aircraft, with tens of thousands of riveted joints per airplane","Plastic toys"],"h":"It has lost dominance elsewhere.","a":2,"id":590},{"d":"wk10-joining","p":79,"q":"Thin sheets can be joined without preliminary drilling by:","o":["Stitching or stapling","Riveting","Bolting","Threaded inserts"],"h":"Common for sheet to wooden backing.","a":0,"id":591},{"d":"wk10-joining","p":80,"q":"Seams are produced by a sequence of bends on tight radii of about:","o":["Five sheet thicknesses","One-half sheet thickness","Ten sheet thicknesses","Zero"],"h":"Lock seams can be sealed with fillers.","a":1,"id":592},{"d":"wk10-joining","p":72,"q":"Non-threaded fasteners are often invisible because they are held by friction within the assembly. The most common visible one is the:","o":["Rivet","Washer","Pin","Retaining ring"],"h":"It sits under a screw head.","a":1,"id":593},{"d":"wk13-ceramics","p":4,"q":"Ceramic materials are:","o":["Inorganic, nonmetallic compounds with ionic or predominantly ionic bonds","Organic carbon-chain materials","Metals held by a sea of electrons","Always amorphous polymers"],"h":"Compounds between metallic and nonmetallic elements.","a":0,"id":594},{"d":"wk13-ceramics","p":4,"q":"The word ceramic comes from the Greek \"keramikos\", meaning:","o":["Hard stone","Burnt stuff","Clay pot","Glass"],"h":"Properties are achieved by firing.","a":1,"id":595},{"d":"wk13-ceramics","p":4,"q":"A covalent bond involves:","o":["Electrostatic attraction between oppositely charged ions","Electron sharing between atoms","A sea of free electrons","Weak van der Waals attraction only"],"h":"It is short range.","a":1,"id":596},{"d":"wk13-ceramics","p":5,"q":"Ceramic engine components permit efficient burning of fuel at higher temperatures and can:","o":["Eliminate the need for a cooling system","Conduct electricity","Be easily welded","Absorb shocks"],"h":"They withstand extreme heat.","a":0,"id":597},{"d":"wk13-ceramics","p":7,"q":"Engineering ceramics are low in cost mainly because:","o":["They are easy to machine","Raw materials are abundant","They need no firing","They are recycled plastics"],"h":"Clay and sand are everywhere.","a":1,"id":598},{"d":"wk13-ceramics","p":7,"q":"The brittleness of ceramics has been reduced by new combinations with:","o":["Plasticisers","Reinforcing fibres or whiskers","Lead","Water"],"h":"Ceramic matrix composites.","a":1,"id":599},{"d":"wk13-ceramics","p":7,"q":"The three main types of engineering ceramics are:","o":["Metal oxide ceramics, glass ceramics, and carbides and nitrides","Earthenware, stoneware and porcelain","Soft, hard and very hard glass","Alumina, zirconia and beryllia"],"h":"Categories A, B and C.","a":0,"id":600},{"d":"wk13-ceramics","p":8,"q":"Aluminas are a family of:","o":["Silicon carbides","Aluminium oxides (Al2O3)","Zirconium oxides","Boron nitrides"],"h":"They serve at 1650°C.","a":1,"id":601},{"d":"wk13-ceramics","p":8,"q":"Which metal oxide ceramic resists thermal shock with low thermal expansion and high thermal conductivity?","o":["Alumina","Beryllia","Zirconia","Silica"],"h":"Beryllium oxide (BeO).","a":1,"id":602},{"d":"wk13-ceramics","p":8,"q":"Zirconia is noted for:","o":["Being inert to most metals with the highest strength to 2204°C","Poor performance at high temperature","Being a glass ceramic","Being used for bulletproof armour"],"h":"A tough oxide ceramic.","a":0,"id":603},{"d":"wk13-ceramics","p":9,"q":"Glass ceramics are formed by:","o":["Pressing powder and sintering","Forming molten glass then crystallising it by heat treatment","Chemical vapour deposition","Vulcanisation"],"h":"Used for cooktops and cookware.","a":1,"id":604},{"d":"wk13-ceramics","p":9,"q":"Glass ceramics have:","o":["Near-zero coefficients of thermal expansion","Very high thermal expansion","High electrical conductivity","Low corrosion resistance"],"h":"They can go from freezer to oven.","a":0,"id":605},{"d":"wk13-ceramics","p":10,"q":"Macor by Corning is a glass ceramic notable because it:","o":["Is transparent","Can be machined with conventional tools","Is magnetic","Melts at 200°C"],"h":"It has the strength of alumina.","a":1,"id":606},{"d":"wk13-ceramics","p":12,"q":"Boron carbide, with very high hardness and low density, is used for:","o":["Bulletproof armour plate and pressure-blasting nozzles","Cookware","Window glass","Heart valves"],"h":"Excellent abrasion resistance.","a":0,"id":607},{"d":"wk13-ceramics","p":13,"q":"The general steps in forming ceramics are:","o":["Crush/grind raw materials, mix with additives, then shape, dry and fire","Melt, cast, quench, temper","Polymerise, mould, cure","Forge, roll, machine"],"h":"Fine particles first.","a":0,"id":608},{"d":"wk13-ceramics","p":14,"q":"The three basic forming processes for ceramics are:","o":["Forging, rolling and extrusion","Casting, plastic forming and pressing","Blowing, drawing and floating","Turning, milling and grinding"],"h":"LSF, plastic state, SSF.","a":1,"id":609},{"d":"wk13-ceramics","p":15,"q":"In slip casting, a suspension of ceramic particles in water is poured into a:","o":["Porous plaster mould that absorbs water from the outer layers","Steel die under pressure","Molten tin bath","Rotating mandrel"],"h":"Excess slip is poured out.","a":0,"id":610},{"d":"wk13-ceramics","p":16,"q":"Slip casting is characterised by:","o":["High production rate and tight dimensional control","Low production rate, limited dimensional control and labour intensity, but low other costs","Very expensive tooling","Only small simple parts"],"h":"Used for bathroom products and dinnerware.","a":1,"id":611},{"d":"wk13-ceramics","p":17,"q":"Which of the following is a plastic (soft/hydroplastic) forming process for ceramics?","o":["Slip casting","Dry pressing","Jiggering","Float process"],"h":"Also extrusion and injection moulding.","a":2,"id":612},{"d":"wk13-ceramics","p":17,"q":"Plastic state forming processes for ceramics tend to:","o":["Orient layers of clay along the direction of material flow","Produce random orientation","Eliminate shrinkage","Require molten material"],"h":"Like grain flow.","a":0,"id":613},{"d":"wk13-ceramics","p":18,"q":"Dry pressing is used for simple ceramic shapes such as:","o":["Bathroom sinks","Floor tiles, whiteware, refractories and abrasives","Bottles","Optical fibres"],"h":"Similar to powder-metal compaction.","a":1,"id":614},{"d":"wk13-ceramics","p":19,"q":"In wet pressing of ceramics, dimensional control is difficult because of:","o":["Low pressure","Shrinkage during drying","Use of molten tin","Lack of a mould"],"h":"High production rates though.","a":1,"id":615},{"d":"wk13-ceramics","p":19,"q":"In hot pressing (pressure sintering), applying pressure and temperature simultaneously:","o":["Reduces porosity, making the part denser and stronger","Increases porosity","Melts the ceramic","Makes it transparent"],"h":"Combined compaction and firing.","a":0,"id":616},{"d":"wk13-ceramics","p":20,"q":"Jiggering is limited to:","o":["Asymmetrical parts with high accuracy","Symmetrical parts with limited dimensional accuracy","Flat sheets","Thin fibres"],"h":"Clay is shaped on a rotating mould with templates.","a":1,"id":617},{"d":"wk13-ceramics","p":21,"q":"In ceramic injection moulding, the thermoplastic binder is removed by:","o":["Washing in water","Pyrolysis, before the part is sintered","Machining","Chemical tempering"],"h":"Burnt out with heat.","a":1,"id":618},{"d":"wk13-ceramics","p":22,"q":"Shrinkage of ceramic parts during drying and firing can be up to about:","o":["1%","5%","20%","50%"],"h":"Of the original wet size.","a":2,"id":619},{"d":"wk13-ceramics","p":22,"q":"Ceramic parts tend to warp or crack during drying and firing because of:","o":["Variations in moisture content caused by differences in wall thickness and complex shape","Too little moisture","Lack of binder","Rapid quenching"],"h":"Uniform walls help.","a":0,"id":620},{"d":"wk13-ceramics","p":22,"q":"Firing (sintering) a ceramic:","o":["Reduces strength","Creates a strong bond between oxide particles and reduces porosity","Melts the part completely","Removes all hardness"],"h":"Similar to powder metallurgy sintering.","a":1,"id":621},{"d":"wk13-ceramics","p":23,"q":"A glaze fired onto a ceramic product gives a glassy coat that:","o":["Improves appearance and strength and makes it impermeable","Makes it conductive","Makes it flexible","Reduces hardness"],"h":"A final finishing step.","a":0,"id":622},{"d":"wk13-ceramics","p":24,"q":"Glass is:","o":["A crystalline metal","An amorphous transparent solid, hard and brittle, resistant to most chemicals except hydrofluoric acid","A thermoset polymer","A ductile ceramic"],"h":"HF etches glass.","a":1,"id":623},{"d":"wk13-ceramics","p":24,"q":"Glass is composed mainly of:","o":["Silica, lime and sodium carbonate","Alumina, zirconia and boron","Carbon and coke","Iron and carbon"],"h":"Sand, limestone and soda ash.","a":0,"id":624},{"d":"wk13-ceramics","p":26,"q":"The glass transition temperature (Tg) is the temperature at which an amorphous solid:","o":["Boils","Becomes brittle on cooling or soft on heating","Crystallises","Becomes magnetic"],"h":"For soda-lime glass, 520-600°C.","a":1,"id":625},{"d":"wk13-ceramics","p":26,"q":"Soda-lime glass accounts for about ____ of all glass produced.","o":["10%","50%","90%","99.9%"],"h":"Bottles, windows, light bulbs.","a":2,"id":626},{"d":"wk13-ceramics","p":26,"q":"A limitation of soda-lime glass is that it:","o":["Is not very resistant to high temperatures, abrupt temperature change or chemicals","Is very expensive","Cannot be made transparent","Has the highest thermal shock resistance"],"h":"It is a soft glass.","a":0,"id":627},{"d":"wk13-ceramics","p":28,"q":"Lead-alkali glass is called \"crystal\" because of its:","o":["Crystalline atomic structure","High index of refraction","Hardness","Heat resistance"],"h":"It is still amorphous.","a":1,"id":628},{"d":"wk13-ceramics","p":28,"q":"Lead glass is used to shield:","o":["Ultraviolet light","Atomic radiation","Magnetic fields","Sound"],"h":"Lead absorbs radiation.","a":1,"id":629},{"d":"wk13-ceramics","p":29,"q":"Borosilicate glass (e.g. Pyrex) is preferred over soda-lime glass for laboratory glassware mainly because it:","o":["Is cheaper and easier to melt","Has a higher coefficient of thermal expansion","Has better resistance to thermal shock and high temperatures","Is always perfectly colourless"],"h":"Developed in 1912 as the first thermal-shock-resistant glass.","a":2,"id":630},{"d":"wk13-ceramics","p":29,"q":"Borosilicate glass is classified as a:","o":["Soft glass","Hard glass","Very hard glass","Light-sensitive glass"],"h":"It softens at relatively high temperatures.","a":1,"id":631},{"d":"wk13-ceramics","p":31,"q":"Aluminosilicate glass, used in space-vehicle windows and high-temperature thermometers, compared with borosilicate:","o":["Costs more and is more difficult to fabricate","Is cheaper","Has lower heat resistance","Is a soft glass"],"h":"High performance applications.","a":0,"id":632},{"d":"wk13-ceramics","p":33,"q":"The most expensive of all glasses, with maximum thermal shock resistance, is:","o":["Borosilicate","Lead crystal","Fused silica","Soda-lime"],"h":"Pure silicon dioxide.","a":2,"id":633},{"d":"wk13-ceramics","p":32,"q":"96% silica glass can withstand:","o":["Only room temperature","The heat of re-entry into Earth's atmosphere","Hydrofluoric acid","Being bent like metal"],"h":"Used on space shuttle exteriors.","a":1,"id":634},{"d":"wk13-ceramics","p":34,"q":"Photochromic glass is used for:","o":["Sunglasses that darken in sunlight or UV and fade when the stimulus is removed","Information storage with true colour permanence","Turning from clear to opal permanently","Radiation shielding"],"h":"Transition lenses.","a":0,"id":635},{"d":"wk13-ceramics","p":34,"q":"Photosensitive glass:","o":["Darkens in sunlight","Changes from clear to opal when exposed to UV and heated","Is used for lead crystal","Is a soda-lime glass"],"h":"Can be chemically machined.","a":1,"id":636},{"d":"wk13-ceramics","p":37,"q":"Glass sheet made by the rolling process has:","o":["A rough surface that must be ground and polished, or is textured by the rollers","A perfect fire-polished finish","No need for any finishing","A tin-coated surface"],"h":"Similar to calendering of plastics.","a":0,"id":637},{"d":"wk13-ceramics","p":38,"q":"In the float process for flat glass, molten glass floats on a bath of:","o":["Water","Molten tin","Molten lead","Oil"],"h":"It is fire polished in the lehr and needs no further polishing.","a":1,"id":638},{"d":"wk13-ceramics","p":38,"q":"Float glass needs no further polishing because:","o":["It is ground after forming","It is fire polished as it solidifies","It is chemically etched","It is rolled with textured rollers"],"h":"The tin bath is perfectly flat.","a":1,"id":639},{"d":"wk13-ceramics","p":39,"q":"Glass tubing is formed around a rotating mandrel, kept open by:","o":["A core","Air pressure blown through the mandrel","Molten tin","A plunger"],"h":"Solid rods are made without air.","a":1,"id":640},{"d":"wk13-ceramics","p":40,"q":"Glass fibres for fibre-optic cable are made by a process similar to:","o":["Wire drawing, using multiple orifices in heated plates","Float glass","Pressing","Slip casting"],"h":"Drawn at up to 520 m/s.","a":0,"id":641},{"d":"wk13-ceramics","p":40,"q":"Thermal and acoustic insulating glass wool is made by:","o":["Float process","A rotating head centrifugal spraying process, similar to making cotton candy","Pressing","Rolling"],"h":"Fine fibres are spun out.","a":1,"id":642},{"d":"wk13-ceramics","p":42,"q":"Glass blowing is used for thin walled containers and light bulbs, but a limitation is that:","o":["Wall thickness cannot be controlled","Surface finish is unacceptable","It is very slow","It cannot be automated"],"h":"Machines can make over 1000 bulbs per minute.","a":0,"id":643},{"d":"wk13-ceramics","p":43,"q":"Glass pressing forms simple open shapes with good accuracy, but cannot be used for:","o":["Thick parts","Thin-walled parts or closed shapes","Open dishes","Lenses"],"h":"A plunger forces a gob into a mould.","a":1,"id":644},{"d":"wk13-ceramics","p":44,"q":"TV picture tubes and missile nose cones are made by glass:","o":["Blowing","Sagging","Centrifugal casting (spinning)","Float process"],"h":"Symmetrical products.","a":2,"id":645},{"d":"wk13-ceramics","p":45,"q":"Sagging is an inexpensive process in which:","o":["Heated glass sheet sags under its own weight into a shallow mould","Glass is blown into a mould","Glass is floated on tin","Glass is drawn into fibres"],"h":"Dishes, lighting diffusers, sunglass lenses.","a":0,"id":646},{"d":"wk13-ceramics","p":46,"q":"Thermally tempered glass, when broken:","o":["Holds together with a plastic layer","Shatters into many small pieces due to stored residual stress energy","Breaks into large sharp shards","Bends without breaking"],"h":"Car side windows.","a":1,"id":647},{"d":"wk13-ceramics","p":46,"q":"Chemical tempering of glass works by:","o":["Quick chilling of the surface","Exchanging atoms in a molten chemical bath, creating residual compressive surface stresses","Laminating plastic between sheets","Annealing"],"h":"A longer-term process.","a":1,"id":648},{"d":"wk13-ceramics","p":46,"q":"Laminated glass, commonly used for automotive windscreens, consists of:","o":["Tough plastic sandwiched between two pieces of glass","Two pieces of tempered glass bonded with epoxy","Glass coated with molten tin","Chemically tempered single sheet"],"h":"The plastic holds pieces if broken.","a":0,"id":649},{"d":"wk13-ceramics","p":47,"q":"Glass sheet is usually \"cut\" by scoring and snapping, which exploits its:","o":["Ductility","Notch sensitivity","Thermal shock resistance","Self-lubrication"],"h":"It breaks along the score.","a":1,"id":650},{"d":"wk13-ceramics","p":48,"q":"Manufactured carbon is composed of:","o":["Pure diamond","Coke and graphite powder bonded with carbon","Silicon carbide and boron","Carbon fibre and epoxy"],"h":"Used for motor brushes.","a":1,"id":651},{"d":"wk13-ceramics","p":48,"q":"Which is a property of manufactured carbon?","o":["Self-lubricating, corrosion resistant, and a good electrical and thermal conductor","Electrical insulator","Highly ductile","Easily attacked by solvents"],"h":"Slides on metals without galling.","a":0,"id":652},{"d":"wk13-ceramics","p":49,"q":"Manufactured carbon is brittle but:","o":["Is notch sensitive","Is not notch sensitive, and its fatigue resistance exceeds most metals","Has poor fatigue resistance","Can be easily welded"],"h":"Scratches don't weaken it much.","a":1,"id":653},{"d":"wk13-ceramics","p":50,"q":"A classic application of manufactured carbon is:","o":["Window glass","Brushes that transfer current to the commutator in electric motors","Bulletproof armour","Cookware"],"h":"Conductive and self-lubricating.","a":1,"id":654},{"d":"wk13-ceramics","p":51,"q":"Pyrolytic carbon coatings for heart valves are made by:","o":["Slip casting","Chemical vapour deposition of carbon and silicon carbide in a fluidised bed furnace","Injection moulding","Sintering"],"h":"Co-depositing onto substrates.","a":1,"id":655},{"d":"wk13-ceramics","p":53,"q":"Carbon-reinforced plastics are replacing metals in aerospace for:","o":["Weight reduction, vibration damping and stealth","Lower stiffness","Electrical insulation","Ease of welding"],"h":"Usage rose from 13% to 54% in one generation.","a":0,"id":656},{"d":"wk13-ceramics","p":54,"q":"Refractory hard metals (RHMs) are:","o":["Pure tungsten castings","Metal-carbide particles bonded together by a metal matrix","Glass ceramics","Carbon fibre composites"],"h":"Cemented carbides.","a":1,"id":657},{"d":"wk13-ceramics","p":54,"q":"Compared with ceramics, RHMs are:","o":["More ductile with better thermal shock and impact resistance, but lower high-temperature compressive strength","More brittle","Higher in operating temperature","Softer than steel"],"h":"Trade-offs between metal and ceramic.","a":0,"id":658},{"d":"wk13-ceramics","p":55,"q":"The most common structural RHM, used for saw blade tips, is:","o":["Titanium carbide","Tungsten carbide","Tantalum carbide","Boron carbide"],"h":"High-cobalt grades for impact resistance.","a":1,"id":659},{"d":"wk13-ceramics","p":55,"q":"RHM parts are made by:","o":["Sand casting","Forging","Conventional powder-metallurgy compacting and sintering","Investment casting"],"h":"Like other carbide tooling.","a":2,"id":660},{"d":"wk13-ceramics","p":55,"q":"Which RHM is used for metal-forming tooling such as draw dies and burnishing rolls?","o":["Tungsten carbide","Titanium carbide","Tungsten-titanium carbide","Tantalum carbide"],"h":"The combination system.","a":2,"id":661}];
